insert into
  public.lessons (title, body, level, grade, hero_image, paid, date)
values
  ('التَّحِيَّاتُ', 'يَسْتَيْقِظُ سَامِي فِي الصَّبَاحِ. يَقُولُ لِأُمِّهِ: «صَبَاحُ الْخَيْرِ يَا أُمِّي». تَقُولُ الْأُمُّ: «صَبَاحُ النُّورِ يَا سَامِي». يَذْهَبُ سَامِي إِلَى الْمَدْرَسَةِ. يَرَى صَدِيقَهُ عُمَرَ. يَقُولُ سَامِي: «السَّلَامُ عَلَيْكُمْ». يَقُولُ عُمَرُ: «وَعَلَيْكُمُ السَّلَامُ». فِي الْمَسَاءِ يَعُودُ سَامِي إِلَى الْبَيْتِ. يَقُولُ لِأَبِيهِ: «مَسَاءُ الْخَيْرِ يَا أَبِي». قَبْلَ النَّوْمِ يَقُولُ: «تُصْبِحُونَ عَلَى خَيْرٍ».', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-01-a1.png', false, '2024-01-10'),
  ('عَائِلَتِي', 'اِسْمِي لَيْلَى. أَنَا أَسْكُنُ مَعَ عَائِلَتِي فِي بَيْتٍ جَمِيلٍ. هَذَا أَبِي، هُوَ طَبِيبٌ. يَعْمَلُ أَبِي فِي الْمُسْتَشْفَى كُلَّ يَوْمٍ. وَهَذِهِ أُمِّي، هِيَ مُعَلِّمَةٌ. تَعْمَلُ أُمِّي فِي الْمَدْرَسَةِ. عِنْدِي أَخٌ كَبِيرٌ اِسْمُهُ كَرِيمٌ. كَرِيمٌ طَالِبٌ فِي الْجَامِعَةِ. وَعِنْدِي أُخْتٌ صَغِيرَةٌ اِسْمُهَا نُورٌ. نُورٌ تَلْعَبُ فِي الْحَدِيقَةِ كُلَّ مَسَاءٍ. فِي يَوْمِ الْجُمُعَةِ نَجْلِسُ مَعًا فِي الْبَيْتِ. أُمِّي تَطْبُخُ طَعَامًا لَذِيذًا، وَأَبِي يَقْرَأُ كِتَابًا. أَنَا أُحِبُّ عَائِلَتِي كَثِيرًا. عَائِلَتِي صَغِيرَةٌ وَلَكِنَّهَا سَعِيدَةٌ.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-02-a1.png', true, '2024-02-05'),
  ('بَيْتِي الْجَمِيلُ', 'أَنَا اسْمِي خَالِدٌ. بَيْتِي صَغِيرٌ وَجَمِيلٌ. فِي بَيْتِي غُرْفَةٌ لِلْجُلُوسِ وَمَطْبَخٌ وَغُرْفَتَانِ لِلنَّوْمِ. غُرْفَتِي وَاسِعَةٌ. فِي غُرْفَتِي سَرِيرٌ وَمَكْتَبٌ وَنَافِذَةٌ كَبِيرَةٌ. مِنَ النَّافِذَةِ أَرَى الْحَدِيقَةَ. فِي الْحَدِيقَةِ شَجَرَةٌ عَالِيَةٌ وَزُهُورٌ جَمِيلَةٌ. الْمَطْبَخُ نَظِيفٌ، وَأُمِّي تَطْبُخُ فِيهِ كُلَّ يَوْمٍ. غُرْفَةُ الْجُلُوسِ كَبِيرَةٌ، وَفِيهَا تِلْفَازٌ وَكَنَبَةٌ مُرِيحَةٌ. فِي الْمَسَاءِ نَجْلِسُ فِيهَا مَعًا. جَدَّتِي تَسْكُنُ مَعَنَا، وَغُرْفَتُهَا قَرِيبَةٌ مِنَ الْمَطْبَخِ. أَنَا أُحِبُّ بَيْتِي لِأَنَّهُ هَادِئٌ وَنَظِيفٌ. الْبَيْتُ مَكَانٌ جَمِيلٌ لِلْعَائِلَةِ.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-03-a1.png', true, '2024-03-03'),
  ('طَعَامِي الْمُفَضَّلُ', 'أَنَا أُحِبُّ الطَّعَامَ اللَّذِيذَ. فِي الصَّبَاحِ آكُلُ خُبْزًا وَجُبْنًا وَأَشْرَبُ حَلِيبًا. أُمِّي تُحِبُّ الشَّايَ، وَأَبِي يَشْرَبُ الْقَهْوَةَ. فِي الظُّهْرِ نَأْكُلُ الْغَدَاءَ مَعًا. الْغَدَاءُ هُوَ أَرُزٌّ وَدَجَاجٌ وَسَلَطَةٌ. السَّلَطَةُ فِيهَا طَمَاطِمُ وَخِيَارٌ. أَنَا أُحِبُّ الْفَوَاكِهَ كَثِيرًا. التُّفَّاحُ طَعَامِي الْمُفَضَّلُ، وَأُخْتِي تُحِبُّ الْمَوْزَ. فِي الْمَسَاءِ نَأْكُلُ عَشَاءً خَفِيفًا. الْعَشَاءُ هُوَ شُورْبَةٌ سَاخِنَةٌ وَخُبْزٌ. بَعْدَ الْعَشَاءِ نَشْرَبُ عَصِيرَ بُرْتُقَالٍ. الطَّعَامُ الصِّحِّيُّ مُهِمٌّ لِلْجِسْمِ. أَنَا آكُلُ الْخُضَارَ وَالْفَوَاكِهَ كُلَّ يَوْمٍ.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-04-a1.png', true, '2024-04-01'),
  ('الْأَلْوَانُ مِنْ حَوْلِي', 'أَنَا أُحِبُّ الْأَلْوَانَ. السَّمَاءُ زَرْقَاءُ، وَالشَّمْسُ صَفْرَاءُ. الشَّجَرَةُ خَضْرَاءُ، وَالْوَرْدَةُ حَمْرَاءُ. عِنْدِي قَلَمٌ أَزْرَقُ وَحَقِيبَةٌ حَمْرَاءُ. قِطَّتِي بَيْضَاءُ وَجَمِيلَةٌ. فِي الْمَسَاءِ تَكُونُ السَّمَاءُ سَوْدَاءَ وَفِيهَا نُجُومٌ. مَا لَوْنُكَ الْمُفَضَّلُ؟ لَوْنِي الْمُفَضَّلُ هُوَ الْأَخْضَرُ.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-05-a1.png', false, '2024-05-12'),
  ('الْأَرْقَامُ مِنْ وَاحِدٍ إِلَى عَشَرَةٍ', 'فِي صَفِّنَا نَتَعَلَّمُ الْأَرْقَامَ. تَقُولُ الْمُعَلِّمَةُ: «عُدُّوا مَعِي: وَاحِدٌ، اِثْنَانِ، ثَلَاثَةٌ، أَرْبَعَةٌ، خَمْسَةٌ». نَحْنُ نَعُدُّ بِصَوْتٍ عَالٍ. ثُمَّ نُكْمِلُ: «سِتَّةٌ، سَبْعَةٌ، ثَمَانِيَةٌ، تِسْعَةٌ، عَشَرَةٌ». عِنْدِي فِي حَقِيبَتِي ثَلَاثَةُ أَقْلَامٍ وَكِتَابَانِ. فِي الصَّفِّ عَشَرَةُ طُلَّابٍ. عَلَى الْمَكْتَبِ خَمْسَةُ كُتُبٍ. تَسْأَلُ الْمُعَلِّمَةُ: «كَمْ نَافِذَةً فِي الصَّفِّ؟». نَقُولُ: «فِي الصَّفِّ أَرْبَعُ نَوَافِذَ». عِنْدِي يَدَانِ، وَفِي كُلِّ يَدٍ خَمْسَةُ أَصَابِعَ. أَنَا أُحِبُّ دَرْسَ الْأَرْقَامِ لِأَنَّهُ سَهْلٌ وَمُمْتِعٌ. فِي الْبَيْتِ أَعُدُّ النُّجُومَ فِي السَّمَاءِ، وَلَكِنَّهَا كَثِيرَةٌ جِدًّا!', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-06-a1.png', true, '2024-06-08'),
  ('يَوْمِي مِنَ الصَّبَاحِ إِلَى الْمَسَاءِ', 'اِسْمِي مَرْيَمُ. أَسْتَيْقِظُ فِي السَّاعَةِ السَّابِعَةِ صَبَاحًا. أَغْسِلُ وَجْهِي وَأُنَظِّفُ أَسْنَانِي. ثُمَّ آكُلُ الْفَطُورَ مَعَ عَائِلَتِي. أَذْهَبُ إِلَى الْمَدْرَسَةِ فِي السَّاعَةِ الثَّامِنَةِ. فِي الْمَدْرَسَةِ أَقْرَأُ وَأَكْتُبُ وَأَلْعَبُ مَعَ صَدِيقَاتِي. أَعُودُ إِلَى الْبَيْتِ فِي الظُّهْرِ. آكُلُ الْغَدَاءَ ثُمَّ أَنَامُ قَلِيلًا. فِي الْمَسَاءِ أَكْتُبُ وَاجِبَاتِي عَلَى مَكْتَبِي. بَعْدَ الْوَاجِبَاتِ أُسَاعِدُ أُمِّي فِي الْمَطْبَخِ. ثُمَّ أُشَاهِدُ التِّلْفَازَ قَلِيلًا مَعَ أَخِي. أَقْرَأُ قِصَّةً قَصِيرَةً قَبْلَ النَّوْمِ. أَنَامُ فِي السَّاعَةِ التَّاسِعَةِ. يَوْمِي جَمِيلٌ وَمُنَظَّمٌ.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-07-a1.png', true, '2024-07-15'),
  ('فِي السُّوقِ', 'يَوْمَ السَّبْتِ أَذْهَبُ مَعَ أُمِّي إِلَى السُّوقِ. السُّوقُ قَرِيبٌ مِنْ بَيْتِنَا. فِي السُّوقِ نَرَى الْخُضَارَ وَالْفَوَاكِهَ. تَشْتَرِي أُمِّي طَمَاطِمَ وَبَطَاطِسَ وَبَصَلًا. أَنَا أَحْمِلُ السَّلَّةَ. نَقِفُ عِنْدَ بَائِعِ الْفَوَاكِهِ. تَسْأَلُ أُمِّي: «بِكَمْ كِيلُو التُّفَّاحِ؟». يَقُولُ الْبَائِعُ: «بِخَمْسَةِ دَرَاهِمَ يَا سَيِّدَتِي». تَشْتَرِي أُمِّي كِيلُو تُفَّاحٍ وَكِيلُو مَوْزٍ. ثُمَّ نَذْهَبُ إِلَى مَحَلِّ الْخُبْزِ. الْخُبْزُ سَاخِنٌ وَرَائِحَتُهُ جَمِيلَةٌ. نَشْتَرِي خَمْسَةَ أَرْغِفَةٍ. قَبْلَ الْعَوْدَةِ تَشْتَرِي لِي أُمِّي عَصِيرًا بَارِدًا. أَنَا أُحِبُّ يَوْمَ السُّوقِ لِأَنَّهُ يَوْمٌ مُمْتِعٌ مَعَ أُمِّي.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-08-a1.png', true, '2024-08-20'),
  ('مَدْرَسَتِي', 'مَدْرَسَتِي كَبِيرَةٌ وَجَمِيلَةٌ. أَذْهَبُ إِلَيْهَا كُلَّ صَبَاحٍ مَعَ أَخِي. فِي الْمَدْرَسَةِ صُفُوفٌ وَمَكْتَبَةٌ وَمَلْعَبٌ وَاسِعٌ. مُعَلِّمَتِي اسْمُهَا الْأُسْتَاذَةُ هُدَى، وَهِيَ طَيِّبَةٌ جِدًّا. فِي الصَّفِّ نَقْرَأُ وَنَكْتُبُ وَنَرْسُمُ. أَنَا أُحِبُّ دَرْسَ الرَّسْمِ كَثِيرًا. فِي الِاسْتِرَاحَةِ أَلْعَبُ مَعَ أَصْدِقَائِي فِي الْمَلْعَبِ. نَلْعَبُ كُرَةَ الْقَدَمِ. بَعْدَ الِاسْتِرَاحَةِ نَذْهَبُ إِلَى الْمَكْتَبَةِ. فِي الْمَكْتَبَةِ كُتُبٌ كَثِيرَةٌ وَقِصَصٌ جَمِيلَةٌ. أَقْرَأُ قِصَّةً عَنِ الْحَيَوَانَاتِ. الْمَدْرَسَةُ بَيْتِي الثَّانِي، وَأَنَا سَعِيدٌ فِيهَا كُلَّ يَوْمٍ.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-09-a1.png', true, '2024-09-10'),
  ('الطَّقْسُ الْيَوْمَ', 'أَنْظُرُ مِنَ النَّافِذَةِ. الطَّقْسُ الْيَوْمَ جَمِيلٌ. الشَّمْسُ مُشْرِقَةٌ وَالسَّمَاءُ صَافِيَةٌ. فِي الشِّتَاءِ يَكُونُ الطَّقْسُ بَارِدًا وَيَنْزِلُ الْمَطَرُ. أَلْبَسُ مِعْطَفًا فِي الشِّتَاءِ. فِي الصَّيْفِ يَكُونُ الطَّقْسُ حَارًّا. أَشْرَبُ مَاءً بَارِدًا فِي الصَّيْفِ. أَنَا أُحِبُّ الرَّبِيعَ لِأَنَّ الزُّهُورَ تَفْتَحُ وَالطَّقْسَ مُعْتَدِلٌ. الْيَوْمَ أَلْعَبُ فِي الْحَدِيقَةِ مَعَ أُخْتِي.', 'A1', '1', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-10-a1.png', false, '2024-10-18'),
  ('رِحْلَةٌ إِلَى الْبَحْرِ', 'فِي الصَّيْفِ الْمَاضِي سَافَرْتُ مَعَ عَائِلَتِي إِلَى مَدِينَةٍ عَلَى الْبَحْرِ. رَكِبْنَا الْقِطَارَ فِي الصَّبَاحِ، ثُمَّ وَصَلْنَا بَعْدَ ثَلَاثِ سَاعَاتٍ. كَانَ الْجَوُّ جَمِيلًا وَالشَّمْسُ سَاطِعَةً. سَبَحْنَا فِي الْبَحْرِ وَلَعِبْنَا عَلَى الرَّمْلِ، ثُمَّ أَكَلْنَا السَّمَكَ فِي مَطْعَمٍ صَغِيرٍ قَرِيبٍ مِنَ الشَّاطِئِ. فِي الْمَسَاءِ مَشَيْنَا عَلَى الشَّاطِئِ وَشَاهَدْنَا غُرُوبَ الشَّمْسِ. كَانَتْ رِحْلَةً رَائِعَةً، وَأُرِيدُ أَنْ أَعُودَ إِلَى هَذِهِ الْمَدِينَةِ فِي الصَّيْفِ الْقَادِمِ لِأَنَّهَا هَادِئَةٌ وَجَمِيلَةٌ.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-11-a2.png', false, '2024-03-02'),
  ('فِي سُوقِ الْخُضَارِ وَالْفَوَاكِهِ', 'كُلَّ يَوْمِ جُمُعَةٍ أَذْهَبُ مَعَ أُمِّي إِلَى السُّوقِ. فِي الْأُسْبُوعِ الْمَاضِي اشْتَرَيْنَا خُضَارًا وَفَوَاكِهَ كَثِيرَةً. سَأَلَتْ أُمِّي الْبَائِعَ: بِكَمْ كِيلُو الطَّمَاطِمِ؟ فَقَالَ: بِثَلَاثَةِ دَرَاهِمَ. اشْتَرَتْ أُمِّي كِيلُوَيْنِ مِنَ الطَّمَاطِمِ، ثُمَّ اشْتَرَيْنَا التُّفَّاحَ وَالْمَوْزَ لِأَنَّ أَبِي يُحِبُّ الْفَوَاكِهَ. فِي النِّهَايَةِ شَرِبْنَا عَصِيرَ الْبُرْتُقَالِ وَعُدْنَا إِلَى الْبَيْتِ سَعِيدَيْنِ وَنَحْنُ نَحْمِلُ الْأَكْيَاسَ الْكَثِيرَةَ. أُحِبُّ السُّوقَ كَثِيرًا لِأَنَّهُ مَلِيءٌ بِالْأَلْوَانِ الْجَمِيلَةِ وَالرَّوَائِحِ الطَّيِّبَةِ وَالنَّاسِ مِنْ كُلِّ مَكَانٍ.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-12-a2.png', false, '2024-03-09'),
  ('هِوَايَتِي الْمُفَضَّلَةُ', 'هِوَايَتِي الْمُفَضَّلَةُ هِيَ الرَّسْمُ. بَدَأْتُ الرَّسْمَ عِنْدَمَا كُنْتُ فِي السَّابِعَةِ مِنْ عُمْرِي. كُلَّ مَسَاءٍ أَجْلِسُ فِي غُرْفَتِي وَأَرْسُمُ الْأَشْجَارَ وَالْبُيُوتَ وَالطُّيُورَ. فِي الشَّهْرِ الْمَاضِي رَسَمْتُ صُورَةً لِجَدَّتِي، ثُمَّ أَهْدَيْتُهَا لَهَا فِي عِيدِ مِيلَادِهَا، فَفَرِحَتْ كَثِيرًا. أُحِبُّ الرَّسْمَ كَثِيرًا لِأَنَّهُ يَجْعَلُنِي هَادِئًا وَسَعِيدًا بَعْدَ يَوْمِ الْمَدْرَسَةِ الطَّوِيلِ. فِي الْمُسْتَقْبَلِ أُرِيدُ أَنْ أُشَارِكَ فِي مَعْرِضٍ لِلرَّسْمِ فِي مَدْرَسَتِي، ثُمَّ أَتَمَنَّى أَنْ أُصْبِحَ رَسَّامًا مَشْهُورًا عِنْدَمَا أَكْبُرُ.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-13-a2.png', false, '2024-03-16'),
  ('عِنْدَ الطَّبِيبِ', 'فِي الْأُسْبُوعِ الْمَاضِي اسْتَيْقَظْتُ فِي الصَّبَاحِ وَكَانَ رَأْسِي يُؤْلِمُنِي كَثِيرًا، وَكَانَتْ حَرَارَتِي مُرْتَفِعَةً. قَالَتْ أُمِّي: يَجِبُ أَنْ تَذْهَبَ إِلَى الطَّبِيبِ. ذَهَبْنَا إِلَى الْمُسْتَشْفَى بِالسَّيَّارَةِ، ثُمَّ انْتَظَرْنَا فِي غُرْفَةِ الِانْتِظَارِ نِصْفَ سَاعَةٍ. دَخَلْتُ إِلَى الطَّبِيبِ فَسَأَلَنِي: مَاذَا تَشْعُرُ؟ قُلْتُ لَهُ: أَشْعُرُ بِأَلَمٍ فِي رَأْسِي وَفِي حَلْقِي. فَحَصَنِي الطَّبِيبُ بِعِنَايَةٍ، ثُمَّ قَالَ: عِنْدَكَ زُكَامٌ شَدِيدٌ، وَلَكِنْ لَا تَقْلَقْ. كَتَبَ لِي دَوَاءً وَقَالَ: اشْرَبِ الْمَاءَ كَثِيرًا وَنَمْ مُبَكِّرًا وَلَا تَخْرُجْ فِي الْبَرْدِ. أَخَذْتُ الدَّوَاءَ مِنَ الصَّيْدَلِيَّةِ، وَبَقِيتُ فِي الْبَيْتِ ثَلَاثَةَ أَيَّامٍ. فِي تِلْكَ الْأَيَّامِ كَانَتْ أُمِّي تُحَضِّرُ لِي شُورْبَةً سَاخِنَةً وَعَصِيرَ لَيْمُونٍ، وَكَانَ أَخِي يُحْضِرُ لِي الْوَاجِبَاتِ مِنَ الْمَدْرَسَةِ. بَعْدَ ثَلَاثَةِ أَيَّامٍ شَعَرْتُ بِتَحَسُّنٍ كَبِيرٍ وَعُدْتُ إِلَى الْمَدْرَسَةِ سَعِيدًا، وَفَرِحَ بِي أَصْدِقَائِي كَثِيرًا. تَعَلَّمْتُ مِنْ هَذِهِ التَّجْرِبَةِ أَنَّ الصِّحَّةَ نِعْمَةٌ كَبِيرَةٌ، وَأَنَّنِي يَجِبُ أَنْ أَلْبَسَ مَلَابِسَ دَافِئَةً فِي الشِّتَاءِ.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-14-a2.png', true, '2024-04-05'),
  ('فُصُولُ السَّنَةِ', 'فِي السَّنَةِ أَرْبَعَةُ فُصُولٍ: الرَّبِيعُ وَالصَّيْفُ وَالْخَرِيفُ وَالشِّتَاءُ. أَنَا أُحِبُّ الرَّبِيعَ كَثِيرًا لِأَنَّ الْجَوَّ فِيهِ مُعْتَدِلٌ وَالْأَزْهَارَ تَتَفَتَّحُ فِي الْحَدَائِقِ. فِي الرَّبِيعِ الْمَاضِي خَرَجْنَا فِي رِحْلَةٍ مَدْرَسِيَّةٍ إِلَى حَدِيقَةٍ كَبِيرَةٍ، فَشَاهَدْنَا الْفَرَاشَاتِ الْمُلَوَّنَةَ وَسَمِعْنَا أَصْوَاتَ الْعَصَافِيرِ. أَمَّا الصَّيْفُ فَهُوَ حَارٌّ جِدًّا، وَفِيهِ نَذْهَبُ إِلَى الْبَحْرِ وَنَسْبَحُ وَنَأْكُلُ الْمُثَلَّجَاتِ الْبَارِدَةَ. وَفِي الْخَرِيفِ تَتَسَاقَطُ أَوْرَاقُ الْأَشْجَارِ وَيُصْبِحُ لَوْنُهَا أَصْفَرَ جَمِيلًا. وَفِي الشِّتَاءِ يَنْزِلُ الْمَطَرُ وَيَكُونُ الْجَوُّ بَارِدًا، فَنَلْبَسُ مَلَابِسَ ثَقِيلَةً وَنَشْرَبُ الْمَشْرُوبَاتِ السَّاخِنَةَ. أَخِي الصَّغِيرُ يُحِبُّ الشِّتَاءَ لِأَنَّهُ يَلْعَبُ بِالْمَطَرِ، أَمَّا أُخْتِي فَتُحِبُّ الْخَرِيفَ لِأَنَّهَا تَجْمَعُ الْأَوْرَاقَ الصَّفْرَاءَ وَتَضَعُهَا فِي دَفْتَرِهَا. قَالَتْ مُعَلِّمَتُنَا فِي الصَّفِّ: لِكُلِّ فَصْلٍ جَمَالُهُ الْخَاصُّ، وَيَجِبُ أَنْ نَشْكُرَ اللهَ عَلَى كُلِّ الْفُصُولِ. وَأَنْتَ يَا صَدِيقِي، أَيُّ فَصْلٍ تُحِبُّ، وَلِمَاذَا؟', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-15-a2.png', true, '2024-04-12'),
  ('رِحْلَةٌ مَعَ الْأَصْدِقَاءِ', 'فِي الْعُطْلَةِ الْمَاضِيَةِ خَرَجْتُ فِي رِحْلَةٍ إِلَى الْجَبَلِ مَعَ ثَلَاثَةٍ مِنْ أَصْدِقَائِي. اسْتَيْقَظْنَا مُبَكِّرِينَ، وَحَضَّرْنَا حَقَائِبَنَا، ثُمَّ رَكِبْنَا الْحَافِلَةَ فِي السَّاعَةِ السَّابِعَةِ صَبَاحًا. كَانَ الطَّرِيقُ طَوِيلًا، وَلَكِنَّنَا لَمْ نَشْعُرْ بِالْمَلَلِ لِأَنَّنَا غَنَّيْنَا وَلَعِبْنَا وَتَكَلَّمْنَا كَثِيرًا. عِنْدَمَا وَصَلْنَا إِلَى الْجَبَلِ مَشَيْنَا فِي طَرِيقٍ ضَيِّقٍ بَيْنَ الْأَشْجَارِ، وَشَاهَدْنَا مَنْظَرًا رَائِعًا مِنَ الْأَعْلَى. جَلَسْنَا تَحْتَ شَجَرَةٍ كَبِيرَةٍ وَأَكَلْنَا الطَّعَامَ الَّذِي أَحْضَرْنَاهُ مَعَنَا، ثُمَّ الْتَقَطْنَا صُوَرًا جَمِيلَةً لِلطَّبِيعَةِ. فِي طَرِيقِ الْعَوْدَةِ كُنَّا مُتْعَبِينَ، فَنَامَ بَعْضُنَا فِي الْحَافِلَةِ. وَصَلْنَا إِلَى بُيُوتِنَا فِي الْمَسَاءِ سَعِيدِينَ وَمُتْعَبِينَ. فِي الْيَوْمِ التَّالِي أَرْسَلَ لَنَا صَدِيقُنَا سَامِي الصُّوَرَ عَلَى الْهَاتِفِ، فَضَحِكْنَا كَثِيرًا عَلَى صُورَةٍ لَهُ وَهُوَ نَائِمٌ فِي الْحَافِلَةِ وَفَمُهُ مَفْتُوحٌ. اتَّفَقْنَا جَمِيعًا عَلَى رِحْلَةٍ جَدِيدَةٍ فِي الشَّهْرِ الْقَادِمِ، وَرُبَّمَا نَذْهَبُ هَذِهِ الْمَرَّةَ إِلَى الْبَحْرِ.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-16-a2.png', true, '2024-04-19'),
  ('مَدِينَتِي الْجَمِيلَةُ', 'أَسْكُنُ فِي مَدِينَةٍ قَدِيمَةٍ وَجَمِيلَةٍ قُرْبَ النَّهْرِ. فِي وَسَطِ الْمَدِينَةِ سُوقٌ قَدِيمٌ، وَفِيهِ مَحَلَّاتٌ صَغِيرَةٌ تَبِيعُ التَّوَابِلَ وَالْمَلَابِسَ وَالْحُلْوِيَّاتِ. بِجَانِبِ السُّوقِ مَسْجِدٌ كَبِيرٌ لَهُ مِئْذَنَةٌ عَالِيَةٌ، وَأَمَامَ الْمَسْجِدِ سَاحَةٌ وَاسِعَةٌ يَجْلِسُ فِيهَا النَّاسُ فِي الْمَسَاءِ. فِي مَدِينَتِي أَيْضًا حَدِيقَةٌ كَبِيرَةٌ، وَمَكْتَبَةٌ عَامَّةٌ أَذْهَبُ إِلَيْهَا كُلَّ أُسْبُوعٍ لِأَقْرَأَ الْقِصَصَ. فِي السَّنَةِ الْمَاضِيَةِ زَارَ مَدِينَتَنَا سُيَّاحٌ كَثِيرُونَ مِنْ بِلَادٍ مُخْتَلِفَةٍ، فَمَشَوْا فِي الشَّوَارِعِ الْقَدِيمَةِ وَالْتَقَطُوا الصُّوَرَ وَاشْتَرَوْا هَدَايَا مِنَ السُّوقِ. سَأَلَنِي سَائِحٌ مَرَّةً عَنِ الطَّرِيقِ إِلَى الْمَسْجِدِ الْكَبِيرِ، فَمَشَيْتُ مَعَهُ وَشَرَحْتُ لَهُ تَارِيخَ الْمَدِينَةِ، فَشَكَرَنِي كَثِيرًا. أَنَا أُحِبُّ مَدِينَتِي كَثِيرًا لِأَنَّ النَّاسَ فِيهَا طَيِّبُونَ وَالشَّوَارِعَ نَظِيفَةٌ وَالتَّارِيخَ فِي كُلِّ مَكَانٍ. عِنْدَمَا أَكْبُرُ أُرِيدُ أَنْ أَعْمَلَ فِيهَا وَأُسَاعِدَ فِي جَعْلِهَا أَجْمَلَ مَدِينَةٍ فِي الْعَالَمِ.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-17-a2.png', true, '2024-05-03'),
  ('نَطْبُخُ مَعًا', 'يَوْمَ السَّبْتِ الْمَاضِي قَرَّرْتُ أَنْ أَطْبُخَ مَعَ أُمِّي طَعَامَ الْغَدَاءِ. قَالَتْ أُمِّي: سَنَطْبُخُ الْيَوْمَ أَرُزًّا بِالدَّجَاجِ وَالْخُضَارِ. ذَهَبْنَا أَوَّلًا إِلَى الْمَطْبَخِ وَغَسَلْنَا أَيْدِيَنَا جَيِّدًا. أَحْضَرْتُ الْبَصَلَ وَالْجَزَرَ وَالطَّمَاطِمَ مِنَ الثَّلَّاجَةِ، ثُمَّ قَطَّعَتْ أُمِّي الْخُضَارَ بِالسِّكِّينِ لِأَنَّ السِّكِّينَ حَادٌّ وَخَطِيرٌ عَلَى الْأَطْفَالِ. وَضَعْنَا الدَّجَاجَ فِي الْقِدْرِ مَعَ قَلِيلٍ مِنَ الْمِلْحِ وَالتَّوَابِلِ، وَانْتَظَرْنَا نِصْفَ سَاعَةٍ. كَانَتْ رَائِحَةُ الطَّعَامِ رَائِعَةً فِي كُلِّ الْبَيْتِ. حَضَّرْتُ أَنَا الْمَائِدَةَ: وَضَعْتُ الصُّحُونَ وَالْمَلَاعِقَ وَالْأَكْوَابَ. عِنْدَمَا جَاءَ أَبِي وَأَخِي جَلَسْنَا جَمِيعًا وَأَكَلْنَا مَعًا. قَالَ أَبِي بَعْدَ أَنْ ذَاقَ الْأَرُزَّ: هَذَا أَلَذُّ طَعَامٍ أَكَلْتُهُ فِي حَيَاتِي! فَفَرِحْتُ كَثِيرًا وَقُلْتُ لَهُ: أَنَا سَاعَدْتُ أُمِّي فِي كُلِّ شَيْءٍ. بَعْدَ الْغَدَاءِ غَسَلْتُ الصُّحُونَ مَعَ أَخِي، ثُمَّ شَرِبْنَا الشَّايَ مَعًا فِي الصَّالَةِ. قَرَّرْتُ مِنْ ذَلِكَ الْيَوْمِ أَنْ أَتَعَلَّمَ الطَّبْخَ مَعَ أُمِّي كُلَّ أُسْبُوعٍ لِأَنَّ الطَّبْخَ مُمْتِعٌ وَمُفِيدٌ.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-18-a2.png', true, '2024-05-10'),
  ('مُكَالَمَةٌ هَاتِفِيَّةٌ', 'فِي مَسَاءِ أَمْسِ رَنَّ هَاتِفُ الْبَيْتِ، فَرَفَعْتُ السَّمَّاعَةَ وَقُلْتُ: أَلُو، مَنْ مَعِي؟ قَالَ صَوْتٌ فَرِحٌ: أَنَا عَمُّكَ خَالِدٌ، أَتَّصِلُ مِنْ مَطَارِ الْمَدِينَةِ! تَفَاجَأْتُ كَثِيرًا لِأَنَّ عَمِّي يَسْكُنُ فِي بَلَدٍ بَعِيدٍ، وَلَمْ نَرَهُ مُنْذُ سَنَتَيْنِ. قَالَ عَمِّي: وَصَلْتُ الْيَوْمَ، وَسَأَزُورُكُمْ غَدًا فِي الصَّبَاحِ، فَأَخْبِرْ وَالِدَكَ مِنْ فَضْلِكَ. أَغْلَقْتُ الْهَاتِفَ وَرَكَضْتُ إِلَى أَبِي وَأَنَا أَصِيحُ: عَمِّي خَالِدٌ وَصَلَ! فَرِحَ أَبِي كَثِيرًا، ثُمَّ اتَّصَلَ بِعَمِّي وَتَكَلَّمَا طَوِيلًا. فِي الْمَسَاءِ سَاعَدْتُ أُمِّي فِي تَنْظِيفِ الْبَيْتِ وَتَحْضِيرِ غُرْفَةِ الضُّيُوفِ. فِي الصَّبَاحِ جَاءَ عَمِّي وَمَعَهُ هَدَايَا كَثِيرَةٌ لَنَا: كِتَابٌ لِي، وَلُعْبَةٌ لِأُخْتِي، وَسَاعَةٌ جَمِيلَةٌ لِأَبِي. جَلَسْنَا حَوْلَهُ نَسْمَعُ حِكَايَاتِهِ عَنْ سَفَرِهِ وَعَنِ الْبِلَادِ الَّتِي زَارَهَا، وَضَحِكْنَا كَثِيرًا عَلَى قِصَصِهِ الْمُضْحِكَةِ. كَانَ يَوْمًا جَمِيلًا لَا أَنْسَاهُ أَبَدًا.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-19-a2.png', true, '2024-05-17'),
  ('فِي الْمَطَارِ', 'فِي الشَّهْرِ الْمَاضِي سَافَرْتُ مَعَ أَبِي بِالطَّائِرَةِ لِأَوَّلِ مَرَّةٍ فِي حَيَاتِي. وَصَلْنَا إِلَى الْمَطَارِ قَبْلَ مَوْعِدِ الرِّحْلَةِ بِثَلَاثِ سَاعَاتٍ لِأَنَّ أَبِي يُحِبُّ الْوُصُولَ مُبَكِّرًا. كَانَ الْمَطَارُ كَبِيرًا جِدًّا وَمَلِيئًا بِالنَّاسِ مِنْ كُلِّ الْبِلَادِ. وَقَفْنَا أَوَّلًا فِي طَابُورٍ طَوِيلٍ، ثُمَّ أَعْطَيْنَا الْمُوَظَّفَةَ جَوَازَيْ سَفَرِنَا وَحَقِيبَتَنَا الْكَبِيرَةَ. أَعْطَتْنَا الْمُوَظَّفَةُ بِطَاقَتَيِ الصُّعُودِ وَقَالَتْ: رِحْلَتُكُمَا مِنَ الْبَوَّابَةِ رَقْمِ خَمْسَةٍ. جَلَسْنَا فِي صَالَةِ الِانْتِظَارِ، وَشَرِبْتُ عَصِيرًا وَأَنَا أُشَاهِدُ الطَّائِرَاتِ مِنَ النَّافِذَةِ الْكَبِيرَةِ. عِنْدَمَا رَكِبْنَا الطَّائِرَةَ شَعَرْتُ بِخَوْفٍ قَلِيلٍ، وَلَكِنَّ أَبِي قَالَ لِي: لَا تَخَفْ، السَّفَرُ بِالطَّائِرَةِ آمِنٌ. وَعِنْدَمَا طَارَتِ الطَّائِرَةُ شَاهَدْتُ مِنَ النَّافِذَةِ الْمَدِينَةَ صَغِيرَةً تَحْتَنَا، وَالْبُيُوتَ مِثْلَ عُلَبِ الْكِبْرِيتِ، وَالسَّيَّارَاتِ مِثْلَ النَّمْلِ. أَحْضَرَتْ لَنَا الْمُضِيفَةُ طَعَامًا وَعَصِيرًا، وَأَعْطَتْنِي ابْتِسَامَةً جَمِيلَةً. كَانَتْ رِحْلَةً لَا تُنْسَى، وَأَتَمَنَّى أَنْ أُسَافِرَ بِالطَّائِرَةِ مَرَّةً أُخْرَى قَرِيبًا.', 'A2', '2', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-20-a2.png', true, '2024-05-24'),
  ('الرياضة طريقي إلى الصحة', 'قرّر سامر أن يغيّر حياته بعد أن شعر بالتعب المُستمرّ في العمل. بدأ يمارس رياضة الجري كلّ صباح في الحديقة القريبة من بيته، رغم أنّ الاستيقاظ المبكر كان صعبًا في البداية.

بعد شهر واحد فقط لاحظ سامر فرقًا كبيرًا؛ أصبح نومه أفضل، وقلّ شعوره بالقلق، بالإضافة إلى أنّه فقد بعض الوزن. قال له الطبيب إنّ الرياضة المنتظمة تحمي القلب وتقوّي العضلات.

اليوم يجري سامر مبتسمًا كلّ صباح، وينصح أصدقاءه قائلًا: إنّ الصحة كنزٌ لا يُقدَّر بثمن.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-21-b1.png', false, '2024-03-05'),
  ('الهاتف الذكي وحياتنا اليومية', 'أصبح الهاتف الذكي جزءًا أساسيًا من حياتنا اليومية، حيث نستخدمه في الدراسة والعمل والتواصل مع الأصدقاء. لكنّ كثيرًا من الناس يقضون ساعات طويلة أمام الشاشة دون أن ينتبهوا إلى مرور الوقت.

تقول ليلى، وهي طالبة جامعية: لا أستطيع أن أتخيّل يومي بدون هاتفي، فأنا أقرأ الأخبار وأتابع محاضراتي عبر التطبيقات. ومع ذلك، قرّرت ليلى مؤخرًا أن تضع قواعد لنفسها؛ فهي لا تستخدم الهاتف أثناء الطعام، ولا تتصفّحه قبل النوم.

يرى الخبراء أنّ التكنولوجيا ليست سيئة في ذاتها، لكنّ الاستخدام المُفرط هو المشكلة الحقيقية. فالهاتف الذي يساعدنا على التعلّم قد يصبح سببًا في العزلة إذا لم نستخدمه استخدامًا واعيًا.

رغم أنّ التخلّي عن الهاتف صعب، فإنّ تنظيم وقت استخدامه ممكن للجميع، ويبدأ بخطوات صغيرة كإغلاق الإشعارات في المساء.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-22-b1.png', true, '2024-04-12'),
  ('حملة لتنظيف الشاطئ', 'نظّمت مجموعة من الشباب في المدينة الساحلية حملةً لتنظيف الشاطئ بعد أن لاحظوا كمية النفايات الكبيرة التي تركها الزوّار في الصيف الماضي. شارك في الحملة أكثر من مئة متطوّع، حيث جمعوا البلاستيك والزجاج في أكياس خاصة لإعادة التدوير.

تقول منى، وهي المُنسّقة العامة للحملة: بدأنا العمل صباحًا متحمّسين، ورغم أنّ الشمس كانت حارّة، لم يتوقف أحد عن العمل حتى المساء. بالإضافة إلى التنظيف، وزّع المتطوعون منشورات توعوية على الزوّار تشرح خطر البلاستيك على الكائنات البحرية.

يؤكّد العلماء أنّ قطعة البلاستيك الواحدة قد تبقى في البحر مئات السنين، وأنّ السلاحف والأسماك تبتلعها ظانّةً أنها طعام. لذلك فإنّ تقليل استخدام البلاستيك مسؤولية الجميع.

انتهت الحملة بنجاح كبير، ووعد المشاركون بتكرارها كلّ ثلاثة أشهر، آملين أن ينضمّ إليهم عدد أكبر في المرة القادمة.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-23-b1.png', true, '2024-05-20'),
  ('أول يوم في الوظيفة الجديدة', 'استيقظ كريم مبكرًا في أول يوم له في الشركة الجديدة، وارتدى أفضل ملابسه وخرج مسرعًا خوفًا من التأخّر. كان قد درس الهندسة في الجامعة، وبحث عن عمل لمدة ستة أشهر قبل أن يحصل على هذه الفرصة.

استقبله مدير القسم بابتسامة، وعرّفه على زملائه الذين رحّبوا به ترحيبًا حارًّا. في البداية شعر كريم بالتوتّر، لكنّ زميلته سارة ساعدته على فهم نظام العمل، حيث شرحت له المشاريع الحالية والبرامج المُستخدمة في القسم.

رغم أنّ اليوم الأول كان مليئًا بالمعلومات الجديدة، عاد كريم إلى البيت سعيدًا. اتصل بوالدته ليخبرها أنّ الجهد الذي بذله في الدراسة لم يذهب سُدًى، وأنّ التعلّم لا يتوقف عند التخرّج؛ فالموظف الناجح هو الذي يطوّر مهاراته باستمرار.

في المساء كتب كريم في دفتره أهدافه للسنة الأولى: إتقان البرامج الجديدة، وبناء علاقات جيدة مع الزملاء، والمشاركة في مشروع كبير واحد على الأقل.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-24-b1.png', true, '2024-06-08'),
  ('عيد في بيت جدّتي', 'في كلّ عيد تجتمع عائلتنا الكبيرة في بيت جدّتي القديم وسط المدينة. تبدأ جدّتي التحضير قبل العيد بأيام، حيث تصنع الحلوى التقليدية بيديها وترفض شراءها من السوق، قائلةً إنّ الحلوى المصنوعة في البيت لها طعم المحبّة.

في صباح العيد نرتدي الملابس الجديدة ونذهب لزيارتها، فنجد البيت مُزيّنًا والروائح الجميلة تملأ المكان. يجلس الكبار يتبادلون الأحاديث والذكريات، بينما يلعب الأطفال في الحديقة فرحين.

رغم أنّ الحياة الحديثة غيّرت كثيرًا من العادات، فإنّ عائلتنا ما زالت متمسّكة بهذه التقاليد؛ لأنّها تقوّي الروابط بين الأجيال وتعلّم الصغار قيمة العائلة.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-25-b1.png', false, '2024-07-15'),
  ('رحلتي إلى مراكش', 'وصلتُ إلى مدينة مراكش في المساء، وكانت تلك أول رحلة لي خارج بلدي. منذ اللحظة الأولى شعرت أنّني انتقلت إلى عالم آخر؛ فالأسواق القديمة مليئة بالألوان والروائح، والباعة ينادون على بضائعهم بأصوات مرتفعة.

في اليوم التالي زرت ساحة جامع الفنا الشهيرة، حيث يجتمع الحكواتيون والموسيقيون وبائعو العصير. جلست في مقهًى صغير أراقب الحركة، وتحدّثت مع رجل عجوز حكى لي عن تاريخ المدينة التي بُنيت قبل أكثر من تسعمئة سنة.

رغم أنّني خطّطت للبقاء ثلاثة أيام فقط، قرّرت تمديد رحلتي أسبوعًا كاملًا. تذوّقت الطاجين والكسكس، واشتريت هدايا تقليدية لعائلتي، بالإضافة إلى أنّني تعلّمت كلمات من اللهجة المغربية.

عدتُ إلى بلدي حاملًا ذكريات لا تُنسى، ومقتنعًا بأنّ السفر هو أفضل مدرسة يتعلّم فيها الإنسان عن العالم وعن نفسه.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-26-b1.png', true, '2024-09-02'),
  ('المكتبة التي غيّرت حياتي', 'عندما انتقلت عائلتي إلى الحيّ الجديد، اكتشفت مكتبة عامة صغيرة بجانب المدرسة. في البداية دخلتها هربًا من حرّ الصيف فقط، لكنّني وجدت فيها عالمًا كاملًا من الكتب والقصص.

كانت أمينة المكتبة، السيدة فاطمة، تعرف مكان كلّ كتاب، وتقترح على الزوّار ما يناسبهم. اقترحت عليّ روايةً قصيرة في البداية، ثم بدأت أقرأ كتابًا كلّ أسبوع. ومع مرور الوقت أصبحت القراءة عادةً يومية لا أستطيع تركها.

بعد سنة كاملة لاحظ معلّمي أنّ لغتي تحسّنت تحسّنًا واضحًا، وأنّني أصبحت أكتب موضوعات أفضل من زملائي. قلت له إنّ الفضل يعود إلى المكتبة التي فتحت لي أبواب المعرفة.

اليوم أتطوّع في المكتبة نفسها كلّ يوم سبت، حيث أساعد الأطفال الصغار على اختيار قصصهم الأولى، آملًا أن تغيّر القراءة حياتهم كما غيّرت حياتي.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-27-b1.png', true, '2024-10-18'),
  ('صديقان رغم الاختلاف', 'تعرّف عمر على خالد في السنة الأولى من الجامعة، وكانا مختلفين تمامًا؛ فعمر هادئ يحبّ القراءة، بينما خالد اجتماعي يحبّ الرياضة والمغامرات. رغم هذا الاختلاف الكبير، نشأت بينهما صداقة قوية.

في السنة الثانية مرض والد عمر، فاضطرّ عمر إلى العمل مساءً لمساعدة عائلته. لاحظ خالد تعب صديقه، فبدأ يشاركه ملخّصات المحاضرات التي يغيب عنها، ويدرس معه في نهاية الأسبوع دون أن يطلب عمر ذلك.

يقول الحكماء إنّ الصديق الحقيقي يظهر وقت الشدّة، وهذا ما أثبته خالد فعلًا. نجح الصديقان في الامتحانات، وتخرّجا معًا حاملين شهادتيهما بفخر.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-28-b1.png', false, '2025-01-10'),
  ('متطوّعون في الشتاء البارد', 'عندما اشتدّ البرد في المدينة، أطلقت جمعية خيرية حملةً لمساعدة العائلات المحتاجة وكبار السن الذين يعيشون وحدهم. انضمّت هدى إلى الحملة بعد أن قرأت إعلانًا في الجامعة، رغم أنّها لم تتطوّع من قبل.

في اليوم الأول وزّعت هدى وزملاؤها البطّانيات والملابس الشتوية على خمسين عائلة، حيث زاروا البيوت بيتًا بيتًا. تقول هدى: لن أنسى وجه السيدة العجوز التي استقبلتنا باكيةً من الفرح؛ في تلك اللحظة فهمت معنى العطاء الحقيقي.

بالإضافة إلى توزيع المساعدات، نظّم المتطوعون وجبات ساخنة يومية في مركز الجمعية، وأنشؤوا فريقًا صغيرًا لزيارة المسنّين والحديث معهم، لأنّ الوحدة قد تكون أقسى من البرد نفسه.

بعد انتهاء الحملة قرّرت هدى الاستمرار في العمل التطوعي، مؤمنةً بأنّ من يساعد الآخرين يساعد نفسه أولًا؛ فالعطاء يمنح الحياة معنًى لا يشترى بالمال.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-29-b1.png', true, '2025-02-14'),
  ('الحياة في المدينة الكبيرة', 'انتقل يوسف من قريته الهادئة إلى العاصمة للدراسة في الجامعة، فوجد نفسه أمام حياة مختلفة تمامًا. في الأسابيع الأولى شعر بالضياع وسط الشوارع المزدحمة والمباني العالية، حيث يمشي الناس مسرعين ولا يعرف أحد جاره.

لكنّ يوسف اكتشف مع الوقت أنّ للمدينة الكبيرة مزايا كثيرة؛ فالمكتبات والمتاحف في كلّ مكان، والمواصلات العامة تعمل طوال اليوم، بالإضافة إلى فرص العمل المتنوعة التي لا توجد في القرية. التحق بنادٍ ثقافي قريب من سكنه، وتعرّف هناك على أصدقاء من مدن مختلفة.

رغم أنّه ما زال يشتاق إلى هدوء القرية وجلسات العائلة، تعلّم يوسف أن يأخذ من المدينة أفضل ما فيها؛ فهو يدرس بجدّ في الأسبوع، ويزور عائلته في نهاية كلّ شهر عائدًا بقلب مطمئن.

يقول يوسف اليوم إنّ المدينة لا تأكل أبناءها كما كان يظنّ، لكنّها تختبر صبرهم وقدرتهم على التكيّف.', 'B1', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-30-b1.png', true, '2025-03-22'),
  ('الإعلام والرأي العام', 'يُعَدّ الإعلام من أقوى الأدوات المؤثّرة في تشكيل الرأي العام في عصرنا الحديث. فالأخبار التي تُبَثّ يوميًا عبر القنوات والمنصّات الرقمية لا تنقل المعلومة فحسب، بل تصوغ مواقف الناس واتجاهاتهم. وفي حين يرى البعض أنّ وسائل الإعلام تؤدّي دورًا توعويًا لا غنى عنه، يحذّر آخرون من أنّها قد تُستَخدم لتوجيه الجماهير نحو مصالح معيّنة. وقد أظهرت دراسات عديدة أنّ تكرار الخبر يزيد من تصديقه، ممّا أدّى إلى انتشار ظاهرة الأخبار الزائفة بسرعة مذهلة. ومن ثَمّ أصبح التحقّق من المصادر مهارة أساسية لكلّ مواطن. بالرغم من الجهود المبذولة لمكافحة التضليل، ما زالت المنصّات الاجتماعية بيئة خصبة لانتشار الشائعات، إذ يُشارَك المحتوى المثير أسرع من المحتوى الدقيق. ولذلك يدعو الخبراء إلى إدراج التربية الإعلامية في المناهج الدراسية، حتى يتعلّم الطلاب كيف يميّزون بين الحقيقة والرأي، وبين الخبر الموثوق والدعاية المقنّعة. فالوعي النقدي هو خطّ الدفاع الأول أمام سيل المعلومات الذي لا يتوقّف. وهكذا يتّضح أنّ مستقبل المجتمعات مرهون إلى حدّ بعيد بقدرة أفرادها على قراءة الإعلام قراءةً واعية ومسؤولة.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-31-b2.png', true, '2024-09-05'),
  ('العولمة بين الفرص والتحدّيات', 'تُعرَّف العولمة بأنّها تزايد الترابط بين دول العالم اقتصاديًا وثقافيًا وتقنيًا، حتى أصبح العالم أشبه بقرية صغيرة. ولا شكّ أنّ العولمة فتحت أبوابًا واسعة أمام التجارة وتبادل المعرفة، إذ يستطيع المستهلك اليوم أن يشتري منتجًا صُنِع في قارّة أخرى بضغطة زرّ. غير أنّ لهذه الظاهرة وجهًا آخر؛ ففي حين استفادت الشركات الكبرى من الأسواق المفتوحة، وجدت الصناعات المحلّية الصغيرة نفسها أمام منافسة قاسية لا تقدر عليها، ممّا أدّى إلى إغلاق كثير منها. وعلى الصعيد الثقافي، يخشى البعض أن تذوب الهويات المحلّية في ثقافة استهلاكية واحدة، فتختفي اللغات واللهجات والعادات شيئًا فشيئًا. بالرغم من هذه المخاوف، يرى المتفائلون أنّ العولمة لا تلغي الخصوصية بالضرورة، بل قد تمنح الثقافات المحلّية منصّات عالمية للانتشار. ومن ثَمّ فإنّ التحدّي الحقيقي ليس في رفض العولمة أو قبولها كلّيًا، وإنّما في إدارتها بحكمة: أن نأخذ منها ما ينفع، وأن نحافظ في الوقت نفسه على ما يميّزنا من لغة وتراث وقيم. وهكذا تبقى العولمة سيفًا ذا حدّين، يتوقّف أثره النهائي على وعي الشعوب وحكمة قادتها في التعامل مع تحوّلات هذا العصر المتسارع.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-32-b2.png', true, '2024-10-12'),
  ('الذكاء الاصطناعي وسوق العمل', 'يشهد العالم تحوّلًا جذريًا بفعل الذكاء الاصطناعي الذي اقتحم ميادين الطب والتعليم والصناعة والإعلام. ولا يكاد يمرّ يوم إلا وتُعلَن فيه تقنية جديدة تَعِد بإنجاز ما كان يستغرق أيامًا في دقائق معدودة. غير أنّ هذا التقدّم المذهل أثار قلقًا مشروعًا حول مستقبل الوظائف؛ فإن استمرّت الأتمتة بهذه الوتيرة، فقد تختفي مهن بأكملها خلال عقد واحد. وفي حين يؤكّد المتشائمون أنّ الآلة ستحلّ محلّ الإنسان في معظم الأعمال الروتينية، يذهب المتفائلون إلى أنّ التقنية لا تلغي الوظائف بقدر ما تعيد تشكيلها، ممّا أدّى إلى ظهور مهن لم تكن موجودة من قبل كمهندس البيانات ومدرّب النماذج اللغوية. ومن ثَمّ فإنّ السؤال الجوهري ليس: هل سيأخذ الذكاء الاصطناعي وظيفتي؟ بل: كيف أطوّر مهاراتي لأعمل إلى جانبه؟ إنّ الاستثمار في التعلّم المستمرّ، وتنمية المهارات الإنسانية كالإبداع والتفكير النقدي والتواصل، هو الضمانة الحقيقية للبقاء في سوق عمل لا يعرف الثبات. فالمستقبل لا ينتظر أحدًا، والتكيّف أصبح شرطًا للنجاح لا خيارًا إضافيًا. وعليه، فمن واجب الحكومات والمؤسسات التعليمية أن تهيّئ الأجيال الجديدة لهذا الواقع عبر برامج تدريبية مرنة تواكب التغيّرات المتلاحقة.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-33-b2.png', true, '2024-11-20'),
  ('اقتصاد الأسرة وفنّ الادّخار', 'إدارة ميزانية الأسرة مهارة لا تقلّ أهمية عن كسب المال نفسه. فكثير من الأسر تعاني ضيقًا ماليًا لا بسبب قلّة الدخل، بل بسبب غياب التخطيط. ينصح الخبراء بتقسيم الدخل إلى ثلاثة أقسام: قسم للحاجات الأساسية، وقسم للرغبات، وقسم للادّخار. وبالرغم من بساطة هذه القاعدة، فإنّ قلّة من الناس يلتزمون بها، ممّا أدّى إلى تراكم الديون لدى أسر كثيرة. ولا يُستثنى من خطر الإنفاق العشوائي أحد إلا من راقب مصروفاته وسجّلها بانتظام. ومن ثَمّ فإنّ الخطوة الأولى نحو الاستقرار المالي هي الوعي: أن تعرف أين يذهب مالك قبل أن تتساءل لماذا اختفى.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-34-b2.png', false, '2024-12-08'),
  ('أنظمة التعليم بين التلقين والإبداع', 'تتباين أنظمة التعليم في العالم تباينًا كبيرًا في فلسفتها وأساليبها. ففي حين تركّز بعض الأنظمة على الحفظ والتلقين وكثرة الامتحانات، تتبنّى أنظمة أخرى نهجًا قائمًا على المشاريع والاستكشاف وحرّية الطالب. وقد أصبحت التجربة الفنلندية مثالًا يُحتذى به عالميًا؛ إذ تُمنَح فيها المدارس استقلالية واسعة، وتُختصر الواجبات المنزلية، ويُنظَر إلى المعلّم نظرة تقدير تليق برسالته. وفي المقابل، ما زالت أنظمة كثيرة تقيس نجاح الطالب بقدرته على استرجاع المعلومات يوم الامتحان، ممّا أدّى إلى تخريج أجيال تحفظ أكثر ممّا تفهم. ومن ثَمّ تتعالى الأصوات المطالِبة بإصلاح جذري يجعل الطالب محورَ العملية التعليمية لا مجرّد متلقٍّ سلبي. إنّ الهدف من التعليم ليس حشو الأذهان بالمعلومات، بل إشعال شغف التعلّم وبناء مهارات التفكير وحلّ المشكلات. وبالرغم من أنّ الإصلاح التعليمي طريق طويل مكلف، فإنّ كلفته تظلّ أقلّ بكثير من كلفة الجهل، فالأمم التي استثمرت في التعليم استثمارًا حقيقيًا هي التي تتصدّر اليوم مؤشّرات الابتكار والتنمية. وما من شكّ في أنّ هذا الاستثمار طويل الأمد هو أصدق مقياس لرؤية أيّ دولة لمستقبلها ولمكانتها بين الأمم.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-35-b2.png', true, '2025-01-15'),
  ('مدخل إلى الأدب العربي والشعر', 'يمتدّ الأدب العربي عبر أكثر من خمسة عشر قرنًا، حاملًا في طيّاته ذاكرة أمّة بأكملها. وقد كان الشعر ديوان العرب الأول؛ فيه سجّلوا أيامهم وأمجادهم وأحزانهم، حتى قيل إنّ القصيدة كانت أمضى من السيف في رفع شأن قبيلة أو خفضه. وتُعَدّ المعلّقات من أشهر ما وصلنا من الشعر الجاهلي، إذ تميّزت بجزالة اللفظ وعمق التصوير. ثم تطوّر الأدب في العصرين الأموي والعباسي تطوّرًا ملحوظًا، فظهرت فنون النثر من رسائل ومقامات، وازدهرت الترجمة، ممّا أدّى إلى تلاقح الثقافة العربية مع ثقافات الأمم الأخرى. وفي العصر الحديث، خرج الشعراء على نظام القصيدة العمودية، فوُلِدت قصيدة التفعيلة ثم قصيدة النثر، وفي حين رحّب بها المجدّدون بوصفها تحريرًا للإبداع، عدّها المحافظون خروجًا على عمود الشعر وأصالته. وبالرغم من هذا الجدل الذي لم يهدأ، يظلّ الأدب العربي شعرًا ونثرًا نهرًا متجدّدًا، يستمدّ من ماضيه العريق قوّةً، ومن حاضره المتغيّر أسئلةً وموضوعات لا تنضب. وهكذا يبرهن هذا التراث الأدبي الزاخر على أنّ اللغة العربية كانت وما زالت وعاءً رحبًا للإبداع الإنساني في أرقى صوره.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-36-b2.png', true, '2025-02-10'),
  ('الهجرة وأحلام الضفّة الأخرى', 'ظاهرة الهجرة قديمة قِدَم الإنسان، لكنّها اتخذت في عصرنا أبعادًا جديدة. فملايين البشر يغادرون أوطانهم كلّ عام بحثًا عن عمل أو أمان أو تعليم أفضل. وفي حين تستفيد الدول المستقبِلة من طاقات المهاجرين وخبراتهم، تخسر الدول المصدِّرة كفاءاتها فيما يُعرَف بهجرة العقول، ممّا أدّى إلى اتساع الفجوة بين الشمال والجنوب. وبالرغم من قسوة الطريق ومخاطره، ما زال كثيرون يرون في الهجرة أملًا لا بديل عنه. ومن ثَمّ يؤكّد الخبراء أنّ معالجة أسباب الهجرة في بلدانها الأصلية، من بطالة وصراعات، أجدى من بناء الأسوار على الحدود. فالأوطان لا تنهض إلا بسواعد أبنائها، والاستثمار في الإنسان داخل بلده هو الحلّ الأعمق والأبقى لهذه الظاهرة المعقّدة.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-37-b2.png', false, '2025-03-05'),
  ('تغيّر المناخ: قضية الجميع', 'لم يعد تغيّر المناخ قضية علمية تُناقَش في المؤتمرات فحسب، بل أصبح واقعًا يلمسه الناس في حياتهم اليومية: موجات حرّ غير مسبوقة، وفيضانات مدمّرة، وجفاف يهدّد الأمن الغذائي لملايين البشر. ويُجمِع العلماء على أنّ النشاط البشري، وخاصة حرق الوقود الأحفوري، هو المسؤول الأول عن ارتفاع درجة حرارة الأرض، ممّا أدّى إلى ذوبان الجليد القطبي وارتفاع مستوى البحار. وفي حين تتحمّل الدول الصناعية الكبرى النصيب الأكبر من الانبعاثات، تدفع الدول الفقيرة الثمن الأفدح، فلا ينجو من تبعات المناخ أحد إلا أنّ الأعباء لا تتوزّع بعدل. وبالرغم من توقيع اتفاقيات دولية عديدة، ما زالت الالتزامات الفعلية دون مستوى الطموح. ومن ثَمّ يشدّد الخبراء على أنّ الحلّ يبدأ من مستويين: سياسات حكومية جريئة تتحوّل بالاقتصاد نحو الطاقة المتجدّدة، وسلوك فردي مسؤول في الاستهلاك والتنقّل. إنّ كوكب الأرض ليس ملكًا لجيلنا وحده، بل أمانة سنُسأل عنها أمام الأجيال القادمة، والتأخّر في العمل اليوم يعني دفع فاتورة مضاعفة غدًا. وبهذا يصبح العمل المناخي اختبارًا حقيقيًا لمدى جدّية البشرية في حماية بيتها المشترك قبل فوات الأوان.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-38-b2.png', true, '2025-04-18'),
  ('تاريخ العلوم عند العرب', 'حين كانت أوروبا تتلمّس طريقها في العصور الوسطى، كانت بغداد وقرطبة والقاهرة منارات للعلم يقصدها الطلاب من كلّ صوب. ففي بيت الحكمة بِبغداد تُرجِمت أمّهات الكتب اليونانية والفارسية والهندية، ثم لم يكتفِ العلماء المسلمون بالنقل، بل أضافوا وابتكروا وصحّحوا. فهذا الخوارزمي يضع أسس علم الجبر الذي ما زال يحمل اسمه العربي في لغات العالم، وذاك ابن الهيثم يؤسّس علم البصريات بمنهج تجريبي سبق عصره بقرون، ممّا أدّى إلى اعتباره رائدًا للمنهج العلمي الحديث. وفي الطب، ظلّ كتاب القانون لابن سينا مرجعًا يُدرَّس في جامعات أوروبا حتى القرن السابع عشر. وفي حين يظنّ البعض أنّ دور العرب اقتصر على حفظ التراث اليوناني ونقله، تؤكّد الدراسات المنصفة أنّ إسهامهم كان إبداعًا أصيلًا غيّر مسار العلم. ومن ثَمّ فإنّ استحضار هذا التاريخ ليس ترفًا ولا حنينًا إلى الماضي، بل تذكير بأنّ النهضة ممكنة متى توافرت شروطها: حرّية البحث، ورعاية العلماء، وإيمان المجتمع بقيمة المعرفة. وما أحوج أمّتنا اليوم إلى استلهام تلك الروح العلمية التي جعلت من حواضرها قبلةً لطلّاب المعرفة من كلّ مكان.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-39-b2.png', true, '2025-05-22'),
  ('التوازن بين العمل والحياة', 'في عالم لا يتوقّف عن الدوران، أصبح التوازن بين العمل والحياة الشخصية مطلبًا صعب المنال. فكثير من الموظّفين يحملون عملهم معهم إلى بيوتهم عبر الهواتف والرسائل، ممّا أدّى إلى تلاشي الحدود بين وقت العمل ووقت الراحة. وبالرغم من أنّ التقنية وُجِدت لتسهّل حياتنا، فإنّها صارت في أحيان كثيرة سببًا في الإرهاق المستمرّ. وفي حين تتبنّى بعض الشركات سياسات مرنة كالعمل عن بُعد وتقليص ساعات الدوام، ما زالت ثقافة تمجيد الانشغال سائدة في بيئات كثيرة. ومن ثَمّ ينصح المختصّون بوضع حدود واضحة: إغلاق بريد العمل بعد الدوام، وتخصيص وقت ثابت للأسرة والرياضة، فالموظّف المرتاح أكثر إنتاجًا وإبداعًا من المنهك.', 'B2', '3', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-40-b2.png', false, '2025-06-30'),
  ('فلسفة اللغة: هل نفكر باللغة أم باللغة نفكر؟', 'تطرح فلسفة اللغة سؤالا قديما متجددا: هل اللغة مجرد وعاء ينقل الأفكار، أم أنها القالب الذي يتشكل فيه الفكر نفسه؟ يذهب فريق من الفلاسفة إلى أن التفكير سابق على اللغة، وأن الكلمات لا تعدو أن تكون أدوات للتعبير عما يجول في الذهن. غير أن فريقا آخر — وعلى رأسه أصحاب الفرضية النسبية اللغوية — يرى أن اللغة تحدد حدود عالمنا، وأن من لا يملك كلمة لمفهوم ما يصعب عليه إدراكه إدراكا دقيقا. وبين هذين الموقفين المتقابلين يقف موقف وسط يقول إن العلاقة بين اللغة والفكر علاقة جدلية: فاللغة تصوغ التفكير، والتفكير بدوره يوسع اللغة ويجدد معجمها. ولعل أبلغ شاهد على ذلك أن المترجم — وهو ينقل نصا من لسان إلى لسان — يكتشف أن بعض المعاني تستعصي على النقل الحرفي، لا لقصور في اللغتين، بل لأن كل لغة تقطع الواقع تقطيعا مختلفا. ومن هنا قيل إن تعلم لغة جديدة ليس اكتساب مفردات فحسب، بل هو اكتساب نظرة جديدة إلى العالم، ونافذة تطل منها الروح على أفق لم تألفه من قبل.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-41-c1.png', true, '2025-01-08'),
  ('البلاغة العربية: الكناية والاستعارة بين الإخفاء والإيحاء', 'تقوم البلاغة العربية على فكرة جوهرية: أن قيمة الكلام ليست في معناه المباشر فحسب، بل في الطريقة التي يصل بها المعنى إلى المتلقي. ومن أبرز أدواتها الكناية والاستعارة. فالكناية لفظ أريد به لازم معناه مع جواز إرادة المعنى الأصلي؛ فحين نقول عن رجل إنه كثير الرماد فإننا نكني عن كرمه وكثرة ضيوفه دون تصريح. أما الاستعارة فهي تشبيه حذف أحد طرفيه، كقولنا رأيت بحرا يخطب في الناس، نريد عالما غزير العلم. وقد رأى عبد القاهر الجرجاني — وهو إمام هذا الفن بلا منازع — أن سر الإعجاز ليس في الألفاظ المفردة، بل في نظمها وتعليق بعضها ببعض، فالمعاني تتفاضل بصورها لا بذواتها. والفرق الدقيق بين الكناية والاستعارة أن الكناية تومئ إلى المعنى من بعيد وتترك للقارئ لذة الاكتشاف، بينما الاستعارة تنقله إلى عالم متخيل دفعة واحدة. ولهذا قيل إن الكناية أبلغ من التصريح، لأنها تثبت المعنى بدليله، فمن كثر رماده فقد كثرت قدوره، ومن كثرت قدوره كثر ضيفانه. وهكذا تتحول اللغة من وسيلة إخبار إلى فن يوازن بين الإخفاء والإيحاء.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-42-c1.png', true, '2025-01-22'),
  ('الأندلس: حضارة على ضفتي المتوسط', 'حين يذكر اسم الأندلس تتداعى إلى الذهن صور قرطبة وإشبيلية وغرناطة، تلك المدن التي غدت في أوج ازدهارها منارات للعلم يقصدها الطلاب من أوروبا كلها. لم تكن الحضارة الأندلسية مجرد امتداد جغرافي للمشرق، بل كانت تجربة فريدة في التعايش؛ فقد تجاور فيها المسلمون واليهود والنصارى، وتلاقحت الثقافات حتى أنجبت فلاسفة من طراز ابن رشد، وأطباء كالزهراوي. ولم يقتصر العطاء على العلوم، فالموشحات كسرت رتابة القصيدة العمودية، وفنون العمارة — وقصر الحمراء شاهدها الأخير — مزجت الزخرفة بالهندسة مزجا يأخذ بالألباب. غير أن هذا المجد لم يدم؛ إذ نخرت الفرقة جسد الدولة، وتقاسمها ملوك الطوائف، فكان سقوط غرناطة خاتمة مؤلمة. ويبقى الدرس الأندلسي ماثلا: أن الحضارات لا تموت بقوة أعدائها بقدر ما تموت بتفكك أبنائها، وأن الإبداع يزدهر حيث تتعدد الروافد.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-43-c1.png', false, '2025-02-05'),
  ('الرواية العربية الحديثة: من المقامة إلى نجيب محفوظ', 'لم تولد الرواية العربية من فراغ، بل وقفت على تراث سردي عريق من المقامات وألف ليلة وليلة وأدب الرحلات. ومع ذلك يؤرخ النقاد لميلادها الفني الناضج برواية زينب لمحمد حسين هيكل، ثم بلغت أوج نضجها على يد نجيب محفوظ الذي حول الحارة المصرية إلى كون روائي كامل، ونال عن ذلك جائزة نوبل. ما الذي صنعه محفوظ تحديدا؟ لقد نقل الرواية من التسلية إلى التساؤل؛ فثلاثيته الشهيرة ليست تاريخ أسرة فحسب، بل تشريح لمجتمع يتأرجح بين التقاليد والتحديث. ثم جاء جيل ما بعد محفوظ فكسر السرد الخطي، واستلهم التراث استلهاما حداثيا، وجرب تعدد الأصوات حتى صار القارئ شريكا في بناء المعنى لا متلقيا سلبيا. وقد فتحت الرواية بابها للأسئلة الكبرى: الهوية، والسلطة، والمنفى، وموقع المرأة، فغدت — كما يقول بعض النقاد — ديوان العرب الجديد بعد أن كان الشعر ديوانهم قرونا طويلة. ولعل أهم ما يميز المشهد الراهن اتساعه الجغرافي؛ فلم تعد القاهرة وبيروت وحدهما مركزين، إذ تتصدر روايات خليجية ومغاربية وسودانية القوائم الأدبية، وتترجم إلى لغات العالم، شاهدة على حيوية لا تنضب.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-44-c1.png', true, '2025-02-19'),
  ('اللغة والهوية: حين يصبح اللسان وطنا', 'يقول المثل: من تعلم لغة قوم أمن مكرهم، لكن العلاقة بين اللغة والهوية أعمق من الأمن والمكر؛ فاللسان وطن يحمله المرء أينما رحل. يشعر المهاجر في غربته أن لغته الأم ملاذه الأخير، فبها يحلم ويغضب ويحب. ومن هنا يفهم القلق الذي يساور المجامع اللغوية على الفصحى أمام زحف العاميات والهجين اللغوي في وسائل التواصل. غير أن المسألة ليست صراعا بين فصحى نقية وعامية دخيلة، فالازدواجية اللغوية سمة لازمت العربية منذ قرون، والحكمة تقتضي توظيف كل مستوى في مقامه. إن الهوية اللغوية ليست قلعة مغلقة بل نهر جار: يحافظ على مجراه وهو يستقبل الروافد. واللافت أن أبناء الجيل الثالث من المهاجرين يعودون أحيانا إلى تعلم العربية بحثا عن جذورهم. وهكذا يتبين أن السؤال الحقيقي ليس: أي لغة نتكلم؟ بل: أي إنسان نريد أن نكون حين نتكلم؟', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-45-c1.png', false, '2025-03-04'),
  ('الصحافة وحرية التعبير: سلطة رابعة أم مرآة مشروخة؟', 'وصفت الصحافة منذ القرن التاسع عشر بأنها السلطة الرابعة، لأنها تراقب السلطات الثلاث وتكشف للناس ما يجري خلف الأبواب الموصدة. وقد دفع صحفيون كثر أثمانا باهظة — من الملاحقة إلى السجن — دفاعا عن حق الجمهور في المعرفة. غير أن العصر الرقمي قلب الموازين؛ فلم يعد احتكار الخبر ممكنا بعد أن صار كل حامل هاتف ناشرا محتملا، ولم تعد المشكلة في شح المعلومات بل في فيضها الذي يختلط فيه الغث بالسمين. ومن هنا برزت ظاهرة الأخبار الزائفة التي تنتشر — كما تثبت الدراسات — أسرع من الأخبار الصحيحة، لأنها تخاطب الانفعال لا العقل. أمام هذا الواقع تنقسم الآراء: فمنهم من يطالب بتشديد القوانين على المحتوى، ومنهم من يحذر من أن التشديد ذريعة لخنق الأصوات المعارضة، فالحد الفاصل بين مكافحة التضليل وتقييد الحرية دقيق ملتبس. والراجح أن الحل لا يكون بالمنع وحده، بل بتربية إعلامية تعلم القارئ أن يسائل المصدر ويقارن الروايات، وبصحافة مهنية تستعيد ثقة جمهورها بالدقة والاستقصاء. فلا حرية بلا مسؤولية، ولا مسؤولية تستقيم في غياب الحرية؛ وبينهما يظل المجتمع يبحث عن توازنه الصعب.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-46-c1.png', true, '2025-03-18'),
  ('سوسيولوجيا المدينة: الغرباء الذين يتجاورون', 'المدينة الحديثة كائن متناقض: تضم الملايين لكن ساكنها قد يشكو الوحدة، وتعد بالفرص لكنها ترسم حدودا خفية بين أحيائها. يدرس علم اجتماع المدينة هذه المفارقات، ويلاحظ أن التحضر السريع في العالم العربي أنتج مدنا مزدوجة: مركز حديث لامع تحيط به أحياء عشوائية يقطنها وافدون من الريف حملوا قيمهم القروية إلى فضاء لا يعترف بها. وقد بين الباحثون أن العمران ليس حجارة فحسب، بل علاقات؛ فالحي الذي تختفي منه ساحات اللقاء تضعف فيه الروابط، وتحل الجيرة الباردة محل التكافل القديم. ومن المفاهيم المضيئة هنا ما يسمى الحق في المدينة: أي حق السكان جميعا — لا الأثرياء وحدهم — في تشكيل فضائهم وخدماته. واللافت أن المقهى الشعبي والسوق القديم يؤديان وظيفة اجتماعية تعجز عنها المجمعات المغلقة، لأنهما يخلطان الطبقات ويتيحان لقاء الغرباء على قدم المساواة. إن مستقبل مدننا لا تقرره الأبراج الزجاجية، بل قدرتها على أن تظل أمكنة يلتقي فيها المختلفون فيتعارفون بدل أن يتجاوروا وهم متباعدون. فالمدينة الناجحة، في جوهرها، نص اجتماعي مفتوح يكتبه سكانها كل يوم، ويعيدون كتابته كلما تبدلت أحوالهم وتطلعاتهم وأحلامهم المشتركة.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-47-c1.png', true, '2025-04-01'),
  ('سيكولوجيا الدافعية: لماذا نبدأ ولماذا نستمر؟', 'يفرق علماء النفس بين نوعين من الدافعية: داخلية تنبع من متعة الفعل ذاته، وخارجية تتعلق بالمكافأة أو العقاب. وقد كشفت تجارب شهيرة عن نتيجة مدهشة: المكافآت الخارجية قد تقتل الشغف أحيانا؛ فالطفل الذي كان يرسم لمتعته ثم صار يكافأ على كل رسمة، قد يتوقف عن الرسم إذا توقفت المكافأة. ويفسر الباحثون ذلك بأن المكافأة تحول الفعل من غاية إلى وسيلة. وتذهب نظرية تقرير المصير إلى أن الدافعية الراسخة تقوم على ثلاث حاجات: الاستقلالية، والكفاءة، والانتماء؛ فمن شعر أنه يختار طريقه، وأنه يتقدم فيه، وأنه ليس وحده، استمر وإن اشتدت العقبات. ولهذا ينصح المتعلمون بأن يربطوا أهدافهم بقيمهم العميقة لا بالمقارنة مع الآخرين، فالمقارنة وقود سريع الاشتعال سريع الخمود. ولعل أخطر أعداء الدافعية الكمال المتوهم: من اشترط على نفسه ألا يخطئ لم يبدأ أصلا. والقاعدة الذهبية أن الحماس يتبع الفعل أكثر مما يسبقه؛ فالبدء الصغير المنتظم يولد شعورا بالكفاءة، والكفاءة تولد رغبة في المواصلة، وهكذا تدور عجلة متسارعة لا يوقفها إلا انتظار الظروف المثالية التي لا تأتي أبدا في حياة أحد من الناس.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-48-c1.png', true, '2025-04-15'),
  ('الترجمة والثقافة: خيانة جميلة أم جسر بين العوالم؟', 'يتردد في أوساط المترجمين قول إيطالي شهير معناه أن الترجمة خيانة، لأن النص حين يعبر إلى لغة أخرى يفقد شيئا من ظلاله. لكن المتأمل يدرك أن هذه الخيانة — إن صح الوصف — خيانة جميلة، فلولاها لبقيت الحكمة حبيسة لغتها. ولنا في حركة الترجمة العباسية عبرة: فقد نقل بيت الحكمة علوم اليونان والفرس والهند فأثمر نهضة علمية كبرى. والمترجم الحق ليس قاموسا متحركا، بل وسيط ثقافي يزن بين الأمانة للنص والوفاء للقارئ، ويعرف أن المثل الشعبي قد يحتاج إلى مكافئ لا إلى ترجمة حرفية تقتل روحه. وتبقى الترجمة في عصرنا — رغم تقدم الترجمة الآلية — عملا إنسانيا في جوهره، لأن الآلة تنقل الكلمات بينما ينقل الإنسان السياق والنبرة والمسكوت عنه. فكل ترجمة قراءة، وكل قراءة تأويل، ولهذا تتجدد ترجمات الأعمال الخالدة في كل جيل دون أن تلغي إحداها الأخرى.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-49-c1.png', false, '2025-04-29'),
  ('ابن خلدون: العمران البشري وفلسفة التاريخ', 'حين كتب ابن خلدون مقدمته الشهيرة في القرن الثامن الهجري لم يكن يؤرخ للوقائع فحسب، بل كان يؤسس علما جديدا سماه علم العمران البشري، يبحث في قوانين الاجتماع الإنساني كما يبحث الطبيب في قوانين البدن. رفض ابن خلدون أسلوب الإخباريين الذين ينقلون الروايات دون تمحيص، ووضع معيارا صارما: ما خالف طبائع العمران فهو إلى الكذب أقرب. ومن أشهر نظرياته العصبية، وهي رابطة التضامن التي تقوم بها الدول؛ فالدولة عنده تولد فتية بعصبية قوية، ثم تترف فتلين، ثم تهرم فتسقط ليرثها من هم أشد عصبية، في دورة تشبه أعمار الأحياء. ولاحظ كذلك أن المغلوب مولع بتقليد الغالب في زيه وعوائده، وأن الظلم مؤذن بخراب العمران، فربط بين العدل والازدهار ربطا سبق به علم الاقتصاد السياسي بقرون. وقد ظل هذا الفكر شبه منسي حتى أعاد الغربيون اكتشافه فعدوه مؤسسا لعلم الاجتماع قبل أوغست كونت بخمسة قرون. ويبقى درس المقدمة الأعمق منهجيا: أن التاريخ ليس قصصا تروى للسمر، بل ظواهر تخضع لقوانين يمكن فهمها، ومن فهم تلك القوانين استطاع أن يقرأ الحاضر ويستشرف القادم.', 'C1', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-50-c1.png', true, '2025-05-13'),
  ('الجاحظ وفنّ المقالة', 'يقف الجاحظ في تاريخ النثر العربي موقف المؤسس الذي لا يُنازَع، فقد جعل من المقالة فنًّا قائمًا بذاته قبل أن يعرف الأدب الحديث هذا المصطلح بقرون. كان يكتب في الجِدّ والهزل معًا، ينتقل من مسألة كلامية عويصة إلى نادرة عن البخلاء، فلا يشعر القارئ بانقطاع النَّفَس ولا بتنافر النسيج. وسرّ ذلك أنه أدرك أن العقل يَملّ إذا طال عليه الجدّ، فكان يستطرد عامدًا متعمدًا، ويجعل الاستطراد عنده بنيةً لا عيبًا، ومنهجًا لا شرودًا. وقد امتاز أسلوبه بالازدواج والترادف، يردف الجملة بأختها ليستوفي المعنى من جهاته كلها، حتى قيل إن كتبه تعلّم العقل قبل أن تعلّم الأدب. ولم يكن علمه محصورًا في اللغة، بل كان موسوعيًّا يأخذ من الكلام والفلسفة وأخبار الحيوان وطبائع البشر، ثم يصهر ذلك كله في قالب ساخر متفحّص، يكشف عن مفارقات المجتمع من غير أن يجرح. ولعل أعظم دروسه للكُتّاب أن الوضوح غاية البلاغة، وأن المعاني مطروحة في الطريق، وإنما الشأن في حسن السبك وجودة العرض، فالفكرة لا تُقنع حتى تُمتِع، ولا تُمتِع حتى تصل إلى القلب من أقصر طريق وأعذبه. ومن عجيب أمره أنه ظل قارئًا نهمًا حتى آخر عمره، يكتري دكاكين الورّاقين فيبيت فيها للنظر في الكتب، وقيل إن الكتب نفسها كانت سبب موته إذ سقطت عليه وقد جاوز التسعين، فكأن حياته وموته معًا كانا فصلين من مقالة واحدة في عشق المعرفة.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-51-c2.png', true, '2025-01-05'),
  ('المتنبي وصورة الذات', 'قلّما عرف الشعر العربي ذاتًا متضخمة كذات المتنبي، فقد جعل من نفسه مركز القصيدة ومدارها، حتى إذا مدح ممدوحًا بدا المديح مرآةً يرى فيها وجهه هو. لم يكن غروره ادعاءً فارغًا، بل كان وعيًا حادًّا بالموهبة في عصر يبيع فيه الشعراء قصائدهم بالدراهم، فأبى هو إلا أن يبيعها بالممالك والولايات. وفي شعره تتجاور الحكمة الجارحة والفخر الصاعق، فيقرر في البيت الواحد قانونًا في طبائع البشر ثم يستثني نفسه منه استثناء الواثق. وقد أدرك النقاد قديمًا أن قوته في هذا التوتر نفسه: توتر بين طموح لا سقف له وواقع يردّه ردًّا عنيفًا، فكلما ازدادت المسافة بين الحلم والحال اشتعلت القصيدة. ثم إن لغته صارمة البناء، يؤثر الفعل على الاسم حين يريد الحركة، ويقدّم ما حقه التأخير حين يريد القصر والتخصيص، فجاءت أبياته كأنها منحوتة في الصخر. ولعل خاتمته المأساوية، إذ قُتل وقيل إن شعره هو الذي قتله، أبلغ تعليق على حياةٍ راهن صاحبها على الكلمة فربح الخلود وخسر كل شيء سواه. وما زال الدارسون إلى اليوم يتنازعون سرّ حضوره، فمنهم من يردّه إلى جرأته في قول ما يضمره الناس ولا يجرؤون عليه، ومنهم من يردّه إلى موسيقاه الفخمة التي تملأ الصدر قبل أن يتبيّن العقل معناها، وكلا الفريقين يقرّ بأن العربية لم تعرف بعده شاعرًا أكثر منه دورانًا على الألسنة.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-52-c2.png', true, '2025-01-12'),
  ('النقد الأدبي الحديث', 'انتقل النقد الأدبي العربي في القرن العشرين من أحكام الذوق المرسلة إلى مناهج تتوسل بالمفاهيم وتحتكم إلى النص. فبعد أن كان الناقد القديم يكتفي بقوله هذا أشعر من هذا، صار الناقد الحديث يسائل البنية واللغة والسياق، ويفرّق بين قصدية المؤلف ودلالة النص وأفق القارئ. وقد تعاقبت على الساحة مناهج شتى: تاريخية تردّ الأدب إلى عصره وبيئته، ونفسية تنقّب في لاوعي المبدع، وبنيوية تعزل النص عن مؤلفه وتدرسه نظامًا مغلقًا من العلاقات، ثم تفكيكية تشكك في ثبات المعنى نفسه. غير أن المنهج المستورد كثيرًا ما اصطدم بخصوصية التراث العربي، فالقصيدة العمودية ذات البيت المستقل لا تستجيب بسهولة لأدوات صيغت لقراءة الرواية الغربية، مما ولّد سجالًا خصبًا حول إمكان نقد عربي ينبع من البلاغة القديمة ويحاور الحداثة من غير ذوبان فيها. والمحصلة أن النقد الحديث لم يلغِ الذوق وإنما هذّبه وأسنده بالحجة، فالناقد الحق يجمع بين حساسية الفنان وصرامة العالم، يقرأ النص قراءة عاشق ثم يعيد قراءته قراءة قاضٍ لا يقبل الدعوى بلا بيّنة. وقد أسهمت الجامعات والدوريات المتخصصة في ترسيخ هذا التحول، فنشأت أجيال من النقاد تتقن لغات أجنبية وتعود إلى أمهات البلاغة العربية في وقت واحد، وصار النقد نفسه نصًّا يُقرأ ويُختلف عليه، له أساليبه وأعلامه ومعاركه التي لا تقل خصوبة عن معارك المبدعين أنفسهم.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-53-c2.png', true, '2025-01-19'),
  ('فلسفة العدل عند الفلاسفة المسلمين', 'لم يكن العدل عند فلاسفة الإسلام فضيلة بين الفضائل فحسب، بل كان نظامًا كونيًّا يجري في الوجود كله. فالفارابي جعل المدينة الفاضلة شبيهة بالبدن السليم، لكل عضو فيها وظيفة، والعدل أن يأخذ كل ذي حق حقه بحسب استعداده ومرتبته، فإذا اختلت المراتب فسدت المدينة كما يفسد البدن باختلال أعضائه. وذهب مسكويه في تهذيب الأخلاق إلى أن العدل وسط بين أطراف الجور، وأنه ثمرة اعتدال القوى الثلاث في النفس: الناطقة والغضبية والشهوية، فمن عدل في نفسه أوشك أن يعدل في رعيته. أما المعتزلة فرفعوا العدل إلى مقام الأصول، إذ قالوا إن الله لا يفعل القبيح ولا يخلّ بالواجب، وإن العقل يدرك حسن الأشياء وقبحها إدراكًا أوليًّا قبل ورود الشرع. وقد ترتب على هذا التصور أثر سياسي بعيد، فإذا كان العدل مدرَكًا بالعقل صار الاحتجاج على الجائر ممكنًا باسم العقل نفسه. وهكذا تضافرت الأخلاق والسياسة والإلهيات في مفهوم واحد، يبدأ من ترتيب النفس وينتهي إلى ترتيب العالم، طلبًا لسعادة لا تتم للفرد إلا في مدينة عادلة. ولم يغفل هؤلاء الفلاسفة الجانب العملي، فقد كتبوا في آداب الملوك ونصائح الوزراء، وجعلوا العمران مرهونًا بالعدل والخراب مقرونًا بالجور، حتى صارت العبارة الجامعة عندهم أن الملك يبقى مع الكفر ولا يبقى مع الظلم، وهي حكمة تتجاوز عصرها إلى كل عصر.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-54-c2.png', true, '2025-01-26'),
  ('لغة القرآن وأثرها في العربية', 'ما من نص فعل في لغةٍ ما فعله القرآن في العربية، فقد حفظها من التشظي الذي أصاب أخواتها الساميات، وجعل لها مرجعًا معياريًّا تعود إليه كلما جنحت. فمن أجله وُضع النحو حين خاف العلماء اللحن على الذكر الحكيم، ومن أجله دُوّنت المعاجم وجُمعت الشواهد ورُحل إلى البوادي تُلتقط الفصاحة من أفواه الأعراب. ثم إن إعجازه البياني فتح بابًا لم يُغلق بعد: فحار البلاغيون في نظمه، وذهب عبد القاهر الجرجاني إلى أن الإعجاز في توخي معاني النحو، أي في العلاقات بين الكلم لا في الكلم مفردةً، فأسس بذلك نظرية النظم التي تعد أنضج ما أنتجه العقل البلاغي العربي. وتسرّبت ألفاظ القرآن وتراكيبه إلى كلام الناس حتى صار الاقتباس منه سمة البلغاء، وصارت أمثاله وصوره نسيجًا في الوجدان الجمعي يستوي فيه المتدين وغيره. وحين جاءت النهضة الحديثة وجدت اللغة محفوظة البنية بفضل هذا النص المركزي، فاستطاعت أن تستوعب علوم العصر بمرونة من حُفظ له أصلٌ صلب، إذ الجذع الراسخ وحده هو الذي يحتمل تطعيم الأغصان الجديدة. ويلمس الدارس هذا الأثر في أدق تفاصيل اللغة: في شيوع صيغ بعينها، وفي بقاء حروف المعاني حية الدلالة، وفي معجم أخلاقي وروحي كامل ما كان ليستقر لولا تردده في آي الذكر صباح مساء على ألسنة الملايين عبر أربعة عشر قرنًا متصلة.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-55-c2.png', true, '2025-02-02'),
  ('السرد في ألف ليلة وليلة', 'تقوم ألف ليلة وليلة على مفارقة مؤسِّسة: امرأة تؤجل موتها بالحكي، فكل ليلة تنجو فيها شهرزاد هي انتصار للسرد على السيف. ومن هذه النواة نبتت بنية فريدة هي الحكاية داخل الحكاية، إذ تنفتح القصة على قصة وتلك على ثالثة كصناديق متداخلة، حتى ينسى القارئ أحيانًا في أي طبقة من طبقات الحكي يقف. وليست هذه التقنية ترفًا، بل هي جوهر الرسالة: فالشخصيات أنفسها تفتدي أرواحها بالحكايات، يقول الشيخ للعفريت احكِ لي حكاية أعجب فأهب لك ثلث دم الرجل، فيتحول السرد إلى عملة يُشترى بها العمر. ثم إن الليالي مزجت العجيب بالمألوف مزجًا لا تنفصم عراه، فالبساط يطير فوق أسواق تضج بالباعة، والجني يخرج من قمقم ليجادل صيادًا فقيرًا في حظه ورزقه، وبهذا أنطقت أحلام العامة وآمالهم في قالب خرافي يفلت من الرقيب. ولما ترجمت إلى لغات أوروبا قلبت موازين السرد الغربي، وأقرّ كبار الروائيين بأن جدتهم الأولى حكّاءة عربية أنقذت روحها بالكلام، فصار تأجيل النهاية سرّ كل قصّ عظيم. ومما يلفت الدارس أن الليالي ظلت قرونًا خارج دائرة الاعتراف الأدبي الرسمي، يستمتع بها الجمهور ويزدريها الفقهاء والأدباء لركاكة لغتها، حتى جاء العصر الحديث فردّ إليها الاعتبار، وصارت مادة خصبة للرواية والمسرح والسينما، وشاهدًا على أن الفن العظيم قد يولد في هامش الثقافة لا في متنها.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-56-c2.png', true, '2025-02-09'),
  ('النهضة العربية الحديثة', 'حين ارتطم الشرق بالغرب مطلع القرن التاسع عشر، أفاق على سؤال ما زال يتردد صداه: لماذا تقدموا وتأخرنا؟ ومن رحم هذا السؤال ولدت النهضة العربية الحديثة، حركةً مزدوجة الوجه، تستلهم التراث وتقتبس من الحداثة في آن. فأرسل المصلحون البعثات وأنشأوا المطابع، وترجموا علوم أوروبا، وأحيوا أمهات الكتب التراثية بالتحقيق والنشر، حتى صار إحياء القديم وجهًا آخر لاستقبال الجديد. وكانت الصحافة قاطرة هذا التحول، إذ هذّبت الفصحى من ركام قرون الانحطاط، وفرضت جملة قصيرة واضحة بدل السجع المتكلف، فولدت لغة وسطى تليق بزمن البرق والجريدة. وانقسم الرواد بين تيار يرى الخلاص في الجوهر الأوروبي حذوًا تامًّا، وتيار يرى أن للأمة شخصية لا تنهض إلا بها، وثالث يحاول التوفيق فيأخذ من الغرب أدواته ومن التراث روحه. ولم تكن النهضة شأنًا أدبيًّا فحسب، بل طالت التعليم والمرأة والحكم وفكرة الوطن نفسها. وقد يقال إنها لم تكتمل، وإن سؤالها الأول ما يزال معلقًا، لكن المنجز اللغوي وحده، وهو تحويل الفصحى إلى لغة حية للعلم والصحافة والرواية، كافٍ لجعلها أخطر منعطف في تاريخ العربية الحديث. ويكفي أن نوازن بين رسالة ديوانية من القرن الثامن عشر ومقالة صحفية من مطلع القرن العشرين لندرك حجم المسافة المقطوعة في جيلين اثنين، مسافة في اللغة والفكر وصورة العالم معًا، قطعها رجال ونساء آمنوا بأن الكلمة أول الطريق إلى تغيير الواقع.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-57-c2.png', true, '2025-02-16'),
  ('إشكالية الفصحى والعامية', 'قلّ أن عرفت أمة ازدواجًا لغويًّا بمثل ما تعرفه العربية، إذ يولد المرء على عامية يحيا بها ثم يتعلم فصحى يقرأ ويكتب بها، فيعيش بين لغتين بينهما نسب ووحشة معًا. وقد احتدم الجدل منذ النهضة: فريق رأى في العامية لغة المستقبل الطبيعية ودعا إلى الكتابة بها، وفريق رأى الدعوة قطيعة مع التراث وتمزيقًا للأمة إلى لهجات متنابذة لا يفهم مغربها مشرقها. والمدقق يجد المسألة أعقد من ثنائية حادة، فبين الفصحى المعربة والعامية الدارجة مستويات متدرجة، يصعد المتكلم بينها وينزل بحسب المقام، فيخطب بمستوى ويتسامر بآخر، ولغة الإعلام اليوم وسطى تأخذ من الطرفين. ثم إن العامية نفسها ليست خصمًا أجنبيًّا، فمعظم مفرداتها فصيح أصابه التطور الصوتي، وهي بنت الفصحى وإن عقّت. وتبقى الفصحى رباط الأمة ووعاء ذاكرتها، وحظها اليوم من التعليم والإعلام خير من حظها أمس، غير أن بقاءها مرهون بقدرتها على أن تكون لغة حياة لا لغة مناسبات.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-58-c2.png', false, '2025-02-23'),
  ('الترجمة الأدبية وحدودها', 'الترجمة الأدبية مغامرة محفوفة بالخسارة منذ سطرها الأول، فالنص الأدبي ليس معاني تُنقل بل نسيج من إيقاع وإيحاء وظلال ثقافية، وما يسلم منه للمترجم هو الهيكل دون الروح إن لم يكن المترجم نفسه فنانًا. ولذلك قيل إن الترجمة خيانة جميلة، تخون الحرف لتخلص للمعنى، أو تخون المعنى لتخلص للأثر. والمترجم الحق يقف من النص موقف المؤول لا الناسخ، يسأل عن وظيفة الكلمة في سياقها قبل أن يسأل عن مقابلها في المعجم، فقد يترجم المثل بمثل يقابله في الثقافة المنقول إليها وإن اختلف اللفظ كله. وفي تاريخ العربية تجربة كبرى شاهدة، فقد ترجم العباسيون فلسفة اليونان فولّدوا مصطلحًا فلسفيًّا عربيًّا ما زلنا ننفق منه، مما يدل على أن الترجمة عند أهلها ليست نقلًا بل توليدًا، وتبقى مع ذلك محدودة بحدّ صارم: هناك في كل نص عظيم بقية لا تُترجم، وتلك البقية هي التي تُتعلم اللغات من أجلها.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-59-c2.png', false, '2025-03-02'),
  ('جماليات الخط العربي', 'حين ضاق المجال أمام التصوير في الحضارة الإسلامية اتسع أمام الحرف، فارتقى الخط العربي من أداة تدوين إلى فن تجريدي خالص، يضاهي في صرامته هندسة العمارة وفي ليونته رقص الأنغام. وقد قنّن ابن مقلة هذا الفن حين جعل النقطة وحدة قياس، والألف معيارًا تُنسب إليه الحروف، فصار للجمال قانون رياضي يضبطه من غير أن يخنقه. ثم تفرعت الأقلام: فالكوفي مهيب التربيع يليق بالمصاحف والمحاريب، والثلث سلطان الخطوط لا يتقنه إلا الأفذاذ، والنسخ سهل جار به القلم في الدواوين والكتب، والديواني مرن متراقص ابتكرته دواوين العثمانيين لمراسلاتها. وامتاز الحرف العربي بقابلية فريدة للمد والتراكب، فالكلمة الواحدة تطول وتقصر وتتعانق حروفها في تكوينات لولبية تجعل من الآية لوحة ومن اللوحة ذكرًا. وبهذا حقق الخط معادلة نادرة بين المقروء والمرئي: فهو نص يُتلى وصورة تُتأمل في آن، حتى إذا وقف أمامه من لا يعرف العربية أدرك جماله إدراكًا خالصًا من المعنى.', 'C2', '4', 'https://hmgwrovvqeezkyfiqula.supabase.co/storage/v1/object/public/lesson-images/cover-60-c2.png', false, '2025-03-09');

-- =========================================================
-- 📖 Grammar notes (title + explanation + example)
-- =========================================================
insert into
  public.lesson_grammar (lesson_id, title, explanation, example)
select l.id, g.title, g.explanation, g.example
from public.lessons l
  join (
    values
      ('التَّحِيَّاتُ', 'الْجُمْلَةُ الْفِعْلِيَّةُ', 'الْجُمْلَةُ الْفِعْلِيَّةُ تَبْدَأُ بِفِعْلٍ، مِثْلَ: يَذْهَبُ، يَقُولُ.', 'يَذْهَبُ سَامِي إِلَى الْمَدْرَسَةِ.'),
      ('عَائِلَتِي', 'هَذَا وَهَذِهِ', 'نَقُولُ «هَذَا» لِلْمُذَكَّرِ وَ«هَذِهِ» لِلْمُؤَنَّثِ.', 'هَذَا أَبِي، وَهَذِهِ أُمِّي.'),
      ('عَائِلَتِي', 'التَّاءُ الْمَرْبُوطَةُ', 'التَّاءُ الْمَرْبُوطَةُ (ة) تَأْتِي فِي آخِرِ الْاِسْمِ الْمُؤَنَّثِ، مِثْلَ: مُعَلِّمَةٌ، صَغِيرَةٌ.', 'أُمِّي مُعَلِّمَةٌ.'),
      ('بَيْتِي الْجَمِيلُ', 'الْجُمْلَةُ الِاسْمِيَّةُ', 'الْجُمْلَةُ الِاسْمِيَّةُ تَبْدَأُ بِاسْمٍ، وَلَهَا مُبْتَدَأٌ وَخَبَرٌ.', 'بَيْتِي صَغِيرٌ وَجَمِيلٌ.'),
      ('بَيْتِي الْجَمِيلُ', 'الصِّفَةُ بَعْدَ الْمَوْصُوفِ', 'الصِّفَةُ تَأْتِي بَعْدَ الِاسْمِ وَتُطَابِقُهُ، مِثْلَ: نَافِذَةٌ كَبِيرَةٌ.', 'فِي الْحَدِيقَةِ شَجَرَةٌ عَالِيَةٌ.'),
      ('طَعَامِي الْمُفَضَّلُ', 'الْفِعْلُ الْمُضَارِعُ مَعَ «أَنَا»', 'الْفِعْلُ الْمُضَارِعُ مَعَ «أَنَا» يَبْدَأُ بِهَمْزَةٍ، مِثْلَ: آكُلُ، أَشْرَبُ، أُحِبُّ.', 'أَنَا آكُلُ خُبْزًا وَأَشْرَبُ حَلِيبًا.'),
      ('طَعَامِي الْمُفَضَّلُ', 'ضَمِيرُ «هُوَ» لِلتَّعْرِيفِ', 'نَسْتَعْمِلُ «هُوَ» بَيْنَ الْمُبْتَدَأِ وَالْخَبَرِ الْمُعَرَّفِ.', 'الْغَدَاءُ هُوَ أَرُزٌّ وَدَجَاجٌ.'),
      ('الْأَلْوَانُ مِنْ حَوْلِي', 'أَلْوَانُ الْمُذَكَّرِ وَالْمُؤَنَّثِ', 'اللَّوْنُ لِلْمُذَكَّرِ مِثْلُ «أَزْرَقُ»، وَلِلْمُؤَنَّثِ مِثْلُ «زَرْقَاءُ».', 'قَلَمٌ أَزْرَقُ، وَسَمَاءٌ زَرْقَاءُ.'),
      ('الْأَرْقَامُ مِنْ وَاحِدٍ إِلَى عَشَرَةٍ', 'كَمْ لِلسُّؤَالِ عَنِ الْعَدَدِ', 'نَسْأَلُ بِـ«كَمْ» عَنِ الْعَدَدِ، وَبَعْدَهَا اسْمٌ مُفْرَدٌ.', 'كَمْ نَافِذَةً فِي الصَّفِّ؟'),
      ('الْأَرْقَامُ مِنْ وَاحِدٍ إِلَى عَشَرَةٍ', 'الْمُثَنَّى', 'الْمُثَنَّى يَدُلُّ عَلَى اثْنَيْنِ، وَنَزِيدُ «انِ» فِي آخِرِ الِاسْمِ.', 'عِنْدِي كِتَابَانِ وَيَدَانِ.'),
      ('يَوْمِي مِنَ الصَّبَاحِ إِلَى الْمَسَاءِ', 'تَرْتِيبُ الْأَحْدَاثِ بِـ«ثُمَّ»', 'نَسْتَعْمِلُ «ثُمَّ» لِنَرْبِطَ بَيْنَ عَمَلٍ وَعَمَلٍ بَعْدَهُ.', 'آكُلُ الْغَدَاءَ ثُمَّ أَنَامُ قَلِيلًا.'),
      ('يَوْمِي مِنَ الصَّبَاحِ إِلَى الْمَسَاءِ', 'الْمُضَارِعُ مَعَ ضَمِيرِ الْمُتَكَلِّمِ', 'الْقِصَّةُ كُلُّهَا بِضَمِيرِ «أَنَا»، فَالْأَفْعَالُ تَبْدَأُ بِالْهَمْزَةِ: أَقْرَأُ، أَكْتُبُ، أَلْعَبُ.', 'أَقْرَأُ وَأَكْتُبُ وَأَلْعَبُ مَعَ صَدِيقَاتِي.'),
      ('فِي السُّوقِ', 'بِكَمْ لِلسُّؤَالِ عَنِ السِّعْرِ', 'نَسْأَلُ بِـ«بِكَمْ» عَنْ سِعْرِ الشَّيْءِ.', 'بِكَمْ كِيلُو التُّفَّاحِ؟'),
      ('فِي السُّوقِ', 'لِأَنَّ لِلتَّعْلِيلِ', 'نَسْتَعْمِلُ «لِأَنَّ» لِنَذْكُرَ السَّبَبَ.', 'أُحِبُّ يَوْمَ السُّوقِ لِأَنَّهُ يَوْمٌ مُمْتِعٌ.'),
      ('مَدْرَسَتِي', 'الْمُضَارِعُ مَعَ «نَحْنُ»', 'الْفِعْلُ الْمُضَارِعُ مَعَ «نَحْنُ» يَبْدَأُ بِالنُّونِ، مِثْلَ: نَقْرَأُ، نَكْتُبُ، نَلْعَبُ.', 'فِي الصَّفِّ نَقْرَأُ وَنَكْتُبُ وَنَرْسُمُ.'),
      ('مَدْرَسَتِي', 'الْإِضَافَةُ مَعَ يَاءِ الْمُتَكَلِّمِ', 'نَزِيدُ يَاءً فِي آخِرِ الِاسْمِ لِتَدُلَّ عَلَى الْمِلْكِيَّةِ، مِثْلَ: مَدْرَسَتِي، أَصْدِقَائِي.', 'مَدْرَسَتِي كَبِيرَةٌ وَجَمِيلَةٌ.'),
      ('الطَّقْسُ الْيَوْمَ', 'كَانَ وَيَكُونُ', 'نَسْتَعْمِلُ «يَكُونُ» لِوَصْفِ الْحَالِ، وَخَبَرُهَا مَنْصُوبٌ.', 'فِي الشِّتَاءِ يَكُونُ الطَّقْسُ بَارِدًا.'),
      ('رِحْلَةٌ إِلَى الْبَحْرِ', 'الْفِعْلُ الْمَاضِي مَعَ نَحْنُ', 'عِنْدَمَا نَتَكَلَّمُ عَنْ شَيْءٍ فَعَلْنَاهُ مَعًا فِي الْمَاضِي، نُضِيفُ (نَا) إِلَى آخِرِ الْفِعْلِ.', 'سَبَحْنَا فِي الْبَحْرِ وَأَكَلْنَا السَّمَكَ.'),
      ('فِي سُوقِ الْخُضَارِ وَالْفَوَاكِهِ', 'حَرْفُ الْجَرِّ (بِـ) لِلسُّؤَالِ عَنِ السِّعْرِ', 'نَسْتَعْمِلُ (بِكَمْ) لِلسُّؤَالِ عَنِ الثَّمَنِ، وَنُجِيبُ بِحَرْفِ الْجَرِّ (بِـ) قَبْلَ السِّعْرِ.', 'بِكَمْ كِيلُو الطَّمَاطِمِ؟ بِثَلَاثَةِ دَرَاهِمَ.'),
      ('هِوَايَتِي الْمُفَضَّلَةُ', 'كَانَ مَعَ الْمُتَكَلِّمِ (كُنْتُ)', 'نَسْتَعْمِلُ (كُنْتُ) لِلْكَلَامِ عَنْ حَالٍ فِي الْمَاضِي.', 'بَدَأْتُ الرَّسْمَ عِنْدَمَا كُنْتُ فِي السَّابِعَةِ مِنْ عُمْرِي.'),
      ('عِنْدَ الطَّبِيبِ', 'كَانَ وَاسْمُهَا وَخَبَرُهَا', 'نَسْتَعْمِلُ (كَانَ) لِلْحَدِيثِ عَنْ حَالٍ فِي الْمَاضِي، وَيَأْتِي بَعْدَهَا اسْمٌ ثُمَّ خَبَرٌ.', 'كَانَتْ حَرَارَتِي مُرْتَفِعَةً.'),
      ('عِنْدَ الطَّبِيبِ', 'فِعْلُ الْأَمْرِ وَالنَّهْيِ', 'نَسْتَعْمِلُ فِعْلَ الْأَمْرِ لِلطَّلَبِ، وَ(لَا) مَعَ الْفِعْلِ الْمُضَارِعِ لِلنَّهْيِ.', 'اشْرَبِ الْمَاءَ كَثِيرًا وَلَا تَخْرُجْ فِي الْبَرْدِ.'),
      ('فُصُولُ السَّنَةِ', 'الْعَدَدُ وَالْمَعْدُودُ (٣–١٠)', 'الْأَعْدَادُ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ يَأْتِي بَعْدَهَا الِاسْمُ جَمْعًا.', 'فِي السَّنَةِ أَرْبَعَةُ فُصُولٍ.'),
      ('فُصُولُ السَّنَةِ', 'التَّعْلِيلُ بِـ(لِأَنَّ)', 'نَسْتَعْمِلُ (لِأَنَّ) لِذِكْرِ السَّبَبِ، وَيَأْتِي بَعْدَهَا اسْمٌ أَوْ ضَمِيرٌ.', 'أُحِبُّ الرَّبِيعَ لِأَنَّ الْجَوَّ فِيهِ مُعْتَدِلٌ.'),
      ('رِحْلَةٌ مَعَ الْأَصْدِقَاءِ', 'الْفِعْلُ الْمَاضِي مَعَ (نَا)', 'عِنْدَمَا نَتَحَدَّثُ عَنْ أَفْعَالٍ فَعَلْنَاهَا مَعًا فِي الْمَاضِي نُضِيفُ (نَا) إِلَى الْفِعْلِ.', 'اسْتَيْقَظْنَا مُبَكِّرِينَ وَرَكِبْنَا الْحَافِلَةَ.'),
      ('رِحْلَةٌ مَعَ الْأَصْدِقَاءِ', 'الرَّبْطُ بِـ(ثُمَّ)', 'نَسْتَعْمِلُ (ثُمَّ) لِرَبْطِ حَدَثَيْنِ يَأْتِي أَحَدُهُمَا بَعْدَ الْآخَرِ بِتَرْتِيبٍ.', 'حَضَّرْنَا حَقَائِبَنَا، ثُمَّ رَكِبْنَا الْحَافِلَةَ.'),
      ('مَدِينَتِي الْجَمِيلَةُ', 'حُرُوفُ الْجَرِّ وَظُرُوفُ الْمَكَانِ', 'نَسْتَعْمِلُ كَلِمَاتٍ مِثْلَ (فِي، بِجَانِبِ، أَمَامَ، قُرْبَ) لِوَصْفِ أَمَاكِنِ الْأَشْيَاءِ.', 'بِجَانِبِ السُّوقِ مَسْجِدٌ كَبِيرٌ، وَأَمَامَ الْمَسْجِدِ سَاحَةٌ وَاسِعَةٌ.'),
      ('مَدِينَتِي الْجَمِيلَةُ', 'جَمْعُ الْمُذَكَّرِ السَّالِمُ', 'نَجْمَعُ بَعْضَ الْأَسْمَاءِ وَالصِّفَاتِ بِإِضَافَةِ (ونَ) فِي حَالَةِ الرَّفْعِ.', 'النَّاسُ فِيهَا طَيِّبُونَ، وَزَارَهَا سُيَّاحٌ كَثِيرُونَ.'),
      ('نَطْبُخُ مَعًا', 'تَرْتِيبُ الْأَحْدَاثِ بِـ(أَوَّلًا وَثُمَّ)', 'نَسْتَعْمِلُ (أَوَّلًا) لِلْحَدَثِ الْأَوَّلِ وَ(ثُمَّ) لِلْحَدَثِ الَّذِي يَأْتِي بَعْدَهُ.', 'ذَهَبْنَا أَوَّلًا إِلَى الْمَطْبَخِ، ثُمَّ قَطَّعَتْ أُمِّي الْخُضَارَ.'),
      ('نَطْبُخُ مَعًا', 'التَّعْلِيلُ بِـ(لِأَنَّ)', 'نَذْكُرُ السَّبَبَ بَعْدَ (لِأَنَّ) لِنُفَسِّرَ لِمَاذَا حَدَثَ الشَّيْءُ.', 'قَطَّعَتْ أُمِّي الْخُضَارَ لِأَنَّ السِّكِّينَ حَادٌّ وَخَطِيرٌ.'),
      ('مُكَالَمَةٌ هَاتِفِيَّةٌ', 'الْفِعْلُ الْمَاضِي وَالْمُسْتَقْبَلُ بِـ(سَـ)', 'نَسْتَعْمِلُ الْفِعْلَ الْمَاضِيَ لِمَا حَدَثَ، وَنُضِيفُ (سَـ) إِلَى الْمُضَارِعِ لِلْمُسْتَقْبَلِ.', 'وَصَلْتُ الْيَوْمَ، وَسَأَزُورُكُمْ غَدًا.'),
      ('مُكَالَمَةٌ هَاتِفِيَّةٌ', '(مُنْذُ) لِلتَّعْبِيرِ عَنِ الْمُدَّةِ', 'نَسْتَعْمِلُ (مُنْذُ) لِنَقُولَ كَمْ مِنَ الْوَقْتِ مَرَّ عَلَى شَيْءٍ.', 'لَمْ نَرَهُ مُنْذُ سَنَتَيْنِ.'),
      ('فِي الْمَطَارِ', 'الْعَدَدُ مَعَ السَّاعَاتِ', 'بَعْدَ الْأَعْدَادِ مِنْ ثَلَاثَةٍ إِلَى عَشَرَةٍ يَأْتِي الِاسْمُ جَمْعًا مَجْرُورًا.', 'وَصَلْنَا قَبْلَ مَوْعِدِ الرِّحْلَةِ بِثَلَاثِ سَاعَاتٍ.'),
      ('فِي الْمَطَارِ', 'النَّهْيُ بِـ(لَا)', 'نَسْتَعْمِلُ (لَا) مَعَ الْفِعْلِ الْمُضَارِعِ الْمَجْزُومِ لِنَطْلُبَ مِنْ شَخْصٍ أَلَّا يَفْعَلَ شَيْئًا.', 'لَا تَخَفْ، السَّفَرُ بِالطَّائِرَةِ آمِنٌ.'),
      ('الرياضة طريقي إلى الصحة', 'إنّ وأخواتها', 'تدخل (إنّ) على الجملة الاسمية فتنصب المبتدأ ويُسمّى اسمها، ويبقى الخبر مرفوعًا ويُسمّى خبرها.', 'إنّ الصحةَ كنزٌ لا يُقدَّر بثمن.'),
      ('الهاتف الذكي وحياتنا اليومية', 'أدوات النفي', 'تُستخدم (لا) لنفي الفعل المضارع، وتُستخدم (ليست) لنفي الجملة الاسمية مع المؤنث.', 'التكنولوجيا ليست سيئة في ذاتها، وليلى لا تستخدم الهاتف أثناء الطعام.'),
      ('الهاتف الذكي وحياتنا اليومية', 'المفعول المطلق', 'مصدر منصوب من لفظ الفعل يؤكّد معناه أو يبيّن نوعه.', 'إذا لم نستخدمه استخدامًا واعيًا.'),
      ('حملة لتنظيف الشاطئ', 'الحال', 'اسم نكرة منصوب يبيّن هيئة صاحبه عند وقوع الفعل، ويجيب عن السؤال: كيف؟', 'بدأنا العمل متحمّسين، ووعدوا بتكرار الحملة آملين أن ينضمّ إليهم عدد أكبر.'),
      ('حملة لتنظيف الشاطئ', 'اسم الفاعل', 'اسم مشتق يدلّ على من قام بالفعل، ويُصاغ من الثلاثي على وزن فاعِل.', 'السلاحف تبتلع البلاستيك ظانّةً أنها طعام.'),
      ('أول يوم في الوظيفة الجديدة', 'المفعول المطلق', 'مصدر منصوب يذكر بعد فعل من لفظه لتأكيد المعنى أو بيان نوعه.', 'رحّبوا به ترحيبًا حارًّا.'),
      ('أول يوم في الوظيفة الجديدة', 'الجملة الموصولة', 'تأتي بعد الاسم الموصول (الذي، التي، الذين) لتوضيح المقصود، وتُسمّى صلة الموصول.', 'الموظف الناجح هو الذي يطوّر مهاراته باستمرار.'),
      ('عيد في بيت جدّتي', 'الحال', 'اسم نكرة منصوب يصف هيئة صاحبه وقت حدوث الفعل.', 'يلعب الأطفال في الحديقة فرحين.'),
      ('رحلتي إلى مراكش', 'الجملة الموصولة', 'جملة تأتي بعد الاسم الموصول لتكمل معناه، ويُسمّى ما بعد الاسم الموصول صلة الموصول.', 'حكى لي عن تاريخ المدينة التي بُنيت قبل أكثر من تسعمئة سنة.'),
      ('رحلتي إلى مراكش', 'الحال', 'اسم نكرة منصوب يبيّن هيئة الفاعل عند حدوث الفعل.', 'عدتُ إلى بلدي حاملًا ذكريات لا تُنسى.'),
      ('المكتبة التي غيّرت حياتي', 'المفعول المطلق', 'مصدر منصوب من لفظ الفعل يؤكّده أو يبيّن نوعه.', 'تحسّنت لغتي تحسّنًا واضحًا.'),
      ('المكتبة التي غيّرت حياتي', 'إنّ وأخواتها', '(إنّ) وأخواتها تنصب المبتدأ وترفع الخبر، وتُستخدم (إنّ) بعد القول.', 'قلت له إنّ الفضل يعود إلى المكتبة.'),
      ('صديقان رغم الاختلاف', 'إنّ وأخواتها', 'تدخل (إنّ) على الجملة الاسمية فتنصب اسمها وترفع خبرها.', 'يقول الحكماء إنّ الصديقَ الحقيقي يظهر وقت الشدّة.'),
      ('متطوّعون في الشتاء البارد', 'الحال', 'اسم نكرة منصوب يبيّن هيئة صاحبه عند وقوع الفعل.', 'استقبلتنا السيدة العجوز باكيةً من الفرح، وقرّرت هدى الاستمرار مؤمنةً بقيمة العطاء.'),
      ('متطوّعون في الشتاء البارد', 'أدوات النفي', 'تُستخدم (لن) لنفي الفعل المضارع في المستقبل وتنصبه، وتُستخدم (لا) لنفي الحاضر.', 'لن أنسى وجه السيدة العجوز. العطاء يمنح الحياة معنًى لا يشترى بالمال.'),
      ('الحياة في المدينة الكبيرة', 'الجملة الموصولة', 'تأتي صلة الموصول بعد الاسم الموصول (التي، الذي) لتوضيح المعنى.', 'فرص العمل المتنوعة التي لا توجد في القرية.'),
      ('الحياة في المدينة الكبيرة', 'الحال', 'اسم نكرة منصوب يصف هيئة صاحبه وقت الفعل.', 'يمشي الناس مسرعين، ويزور عائلته عائدًا بقلب مطمئن.'),
      ('الإعلام والرأي العام', 'المبني للمجهول', 'يُحذَف الفاعل ويُرفَع المفعول به نائبًا عنه، ويُضَمّ أول الفعل ويُكسَر ما قبل آخره في الماضي.', 'الأخبار التي تُبَثّ يوميًا عبر القنوات.'),
      ('الإعلام والرأي العام', 'ممّا أدّى إلى (التعبير عن النتيجة)', 'تُستخدم (ممّا أدّى إلى) لربط سبب بنتيجته، ويأتي بعدها مصدر أو اسم.', 'تكرار الخبر يزيد من تصديقه، ممّا أدّى إلى انتشار الأخبار الزائفة.'),
      ('العولمة بين الفرص والتحدّيات', 'في حين (للمقابلة)', 'تُستخدم (في حين) للمقارنة بين أمرين متقابلين في جملة واحدة.', 'في حين استفادت الشركات الكبرى، وجدت الصناعات الصغيرة نفسها أمام منافسة قاسية.'),
      ('العولمة بين الفرص والتحدّيات', 'المبني للمجهول في الماضي', 'يُبنى الفعل الماضي للمجهول بضمّ أوله وكسر ما قبل آخره، ويصبح المفعول نائب فاعل.', 'منتجًا صُنِع في قارّة أخرى.'),
      ('الذكاء الاصطناعي وسوق العمل', 'أسلوب الشرط بـ(إنْ)', 'تربط أداة الشرط (إنْ) بين فعل الشرط وجوابه، وقد يقترن الجواب بالفاء إذا كان جملة اسمية أو مسبوقًا بـ(قد).', 'فإن استمرّت الأتمتة بهذه الوتيرة، فقد تختفي مهن بأكملها.'),
      ('الذكاء الاصطناعي وسوق العمل', 'المصدر المؤوّل', 'يتكوّن المصدر المؤوّل من (أنّ) واسمها وخبرها أو (أنْ) والفعل، ويُؤوَّل بمصدر صريح يقع فاعلًا أو مفعولًا أو خبرًا.', 'يؤكّد المتشائمون أنّ الآلة ستحلّ محلّ الإنسان — أي: حلولَ الآلةِ محلَّ الإنسان.'),
      ('اقتصاد الأسرة وفنّ الادّخار', 'الاستثناء بـ(إلا)', 'يتكوّن أسلوب الاستثناء من المستثنى منه وأداة الاستثناء والمستثنى. وإذا كان الكلام منفيًا ناقصًا أُعرِب ما بعد (إلا) حسب موقعه في الجملة.', 'لا يُستثنى من خطر الإنفاق العشوائي أحد إلا من راقب مصروفاته.'),
      ('أنظمة التعليم بين التلقين والإبداع', 'المبني للمجهول في المضارع', 'يُبنى الفعل المضارع للمجهول بضمّ أوله وفتح ما قبل آخره.', 'تُمنَح المدارس استقلالية واسعة، ويُنظَر إلى المعلّم نظرة تقدير.'),
      ('أنظمة التعليم بين التلقين والإبداع', 'التمييز', 'التمييز اسم نكرة منصوب يوضّح إبهام ما قبله، ويأتي بعد المصدر لبيان نوعه.', 'تتباين أنظمة التعليم تباينًا كبيرًا — استثمرت في التعليم استثمارًا حقيقيًا.'),
      ('مدخل إلى الأدب العربي والشعر', 'المبني للمجهول مع واو الجماعة وغيرها', 'يُبنى الماضي للمجهول بضمّ أوله وكسر ما قبل آخره، ويصبح المفعول نائب فاعل مرفوعًا.', 'فوُلِدت قصيدة التفعيلة ثم قصيدة النثر.'),
      ('مدخل إلى الأدب العربي والشعر', 'التمييز بعد اسم التفضيل والمصدر', 'يأتي التمييز نكرة منصوبة ليزيل إبهام ما قبله من مصدر أو اسم مبهم.', 'تطوّر الأدب تطوّرًا ملحوظًا — يستمدّ من ماضيه قوّةً ومن حاضره أسئلةً.'),
      ('الهجرة وأحلام الضفّة الأخرى', 'اسم الفاعل واسم المفعول من غير الثلاثي', 'يُصاغان من مضارع الفعل بإبدال حرف المضارعة ميمًا مضمومة، مع كسر ما قبل الآخر لاسم الفاعل وفتحه لاسم المفعول.', 'الدول المستقبِلة (اسم فاعل) — الدول المصدِّرة (اسم فاعل).'),
      ('تغيّر المناخ: قضية الجميع', 'المبني للمجهول في المضارع', 'يُضَمّ حرف المضارعة ويُفتَح ما قبل الآخر، ويرتفع المفعول نائب فاعل.', 'قضية تُناقَش في المؤتمرات — أمانة سنُسأل عنها.'),
      ('تغيّر المناخ: قضية الجميع', 'التوكيد بـ(إنّ)', 'تدخل (إنّ) على الجملة الاسمية لتوكيد مضمونها، فتنصب المبتدأ اسمًا لها وترفع الخبر خبرًا لها.', 'إنّ كوكب الأرض ليس ملكًا لجيلنا وحده.'),
      ('تاريخ العلوم عند العرب', 'المبني للمجهول', 'يُبنى الفعل للمجهول حين يكون التركيز على الحدث لا الفاعل؛ بضمّ أول الماضي وكسر ما قبل آخره، وضمّ أول المضارع وفتح ما قبل آخره.', 'تُرجِمت أمّهات الكتب — مرجع يُدرَّس في جامعات أوروبا.'),
      ('تاريخ العلوم عند العرب', 'متى الشرطية', '(متى) اسم شرط للزمان يربط بين شرط وجوابه.', 'النهضة ممكنة متى توافرت شروطها.'),
      ('التوازن بين العمل والحياة', 'بالرغم من (للتعبير عن التناقض)', 'تُستخدم (بالرغم من) متبوعة باسم أو مصدر مؤوّل للتعبير عن تعارض بين أمرين، وغالبًا يأتي الجواب مقترنًا بالفاء.', 'بالرغم من أنّ التقنية وُجِدت لتسهّل حياتنا، فإنّها صارت سببًا في الإرهاق.'),
      ('فلسفة اللغة: هل نفكر باللغة أم باللغة نفكر؟', 'الجملة الاعتراضية', 'جملة تعترض بين جزأي الكلام لتوضيح أو تأكيد، وتوضع غالبا بين شرطتين أو فاصلتين، ولا محل لها من الإعراب.', 'فالمترجم — وهو ينقل نصا من لسان إلى لسان — يكتشف صعوبة النقل الحرفي.'),
      ('فلسفة اللغة: هل نفكر باللغة أم باللغة نفكر؟', 'أسلوب القصر بـ(لا... بل)', 'يقصر الحكم على معنى معين بنفي الأول وإثبات الثاني، فيقوي الحجة ويوجه انتباه القارئ.', 'تستعصي على النقل الحرفي، لا لقصور في اللغتين، بل لأن كل لغة تقطع الواقع تقطيعا مختلفا.'),
      ('البلاغة العربية: الكناية والاستعارة بين الإخفاء والإيحاء', 'الكناية', 'أسلوب بلاغي يذكر فيه اللفظ ويراد لازم معناه، وهي أبلغ من التصريح لأنها تثبت المعنى مع دليله.', 'فلان كثير الرماد: كناية عن الكرم وكثرة الضيوف.'),
      ('البلاغة العربية: الكناية والاستعارة بين الإخفاء والإيحاء', 'الاستعارة التصريحية', 'استعارة صرح فيها بالمشبه به وحذف المشبه، فينتقل الذهن من المعنى الحقيقي إلى المعنى المجازي بقرينة.', 'رأيت بحرا يخطب في الناس: شبه العالم بالبحر ثم حذف المشبه.'),
      ('الأندلس: حضارة على ضفتي المتوسط', 'الجملة الاعتراضية للتعليق', 'تعترض جملة بين أجزاء الكلام لإضافة حكم أو شهادة دون قطع السياق، وتحاط غالبا بشرطتين.', 'وفنون العمارة — وقصر الحمراء شاهدها الأخير — مزجت الزخرفة بالهندسة.'),
      ('الرواية العربية الحديثة: من المقامة إلى نجيب محفوظ', 'أسلوب الاستفهام البلاغي للتشويق', 'يطرح الكاتب سؤالا لا ينتظر جوابا من القارئ بل يجيب عنه بنفسه، لشد الانتباه وتنظيم العرض.', 'ما الذي صنعه محفوظ تحديدا؟ لقد نقل الرواية من التسلية إلى التساؤل.'),
      ('الرواية العربية الحديثة: من المقامة إلى نجيب محفوظ', 'الإضافة اللفظية والمعنوية', 'الإضافة المعنوية تفيد التعريف أو التخصيص (ديوان العرب)، أما اللفظية فإضافة الوصف إلى معموله ولا تفيد إلا التخفيف.', 'ديوان العرب: إضافة معنوية أكسبت المضاف تعريفا.'),
      ('اللغة والهوية: حين يصبح اللسان وطنا', 'التشبيه البليغ', 'تشبيه حذفت منه الأداة ووجه الشبه، فيقوى الادعاء بأن المشبه هو المشبه به نفسه.', 'اللسان وطن يحمله المرء أينما رحل.'),
      ('الصحافة وحرية التعبير: سلطة رابعة أم مرآة مشروخة؟', 'لا النافية للجنس', 'تنفي الحكم عن جنس اسمها كله، ويبنى اسمها على الفتح إذا كان مفردا، ويفيد الأسلوب التوكيد والشمول.', 'فلا حرية بلا مسؤولية، ولا مسؤولية تستقيم في غياب الحرية.'),
      ('الصحافة وحرية التعبير: سلطة رابعة أم مرآة مشروخة؟', 'نائب الفاعل مع الفعل المبني للمجهول', 'إذا حذف الفاعل ناب عنه المفعول به ورفع، ويستعمل حين يكون الفاعل معلوما من السياق أو غير مهم.', 'وصفت الصحافة بأنها السلطة الرابعة — الصحافة نائب فاعل مرفوع.'),
      ('سوسيولوجيا المدينة: الغرباء الذين يتجاورون', 'النعت السببي', 'نعت يصف اسما بعده مرفوعا به متصلا بضمير يعود على المنعوت، فيتبع ما قبله في الإعراب ويراعي ما بعده في التذكير والتأنيث.', 'هذه مدينة مزدحمة شوارعها — مزدحمة نعت سببي والشوارع فاعل له.'),
      ('سوسيولوجيا المدينة: الغرباء الذين يتجاورون', 'بدل البعض من الكل', 'بدل يمثل جزءا من المبدل منه ويتصل بضمير يعود عليه، ويعرب بإعراب متبوعه.', 'حق السكان جميعا — لا الأثرياء وحدهم — في تشكيل فضائهم.'),
      ('سيكولوجيا الدافعية: لماذا نبدأ ولماذا نستمر؟', 'أسلوب الشرط بـ(من)', 'تستعمل (من) الشرطية للعاقل وتجزم فعلين، ويفيد الأسلوب التعميم وصياغة القواعد.', 'من شعر أنه يختار طريقه استمر وإن اشتدت العقبات.'),
      ('سيكولوجيا الدافعية: لماذا نبدأ ولماذا نستمر؟', 'التشبيه التمثيلي', 'تشبيه صورة مركبة بصورة مركبة، يجسد المعنى المجرد في مشهد حسي.', 'فالمقارنة وقود سريع الاشتعال سريع الخمود.'),
      ('الترجمة والثقافة: خيانة جميلة أم جسر بين العوالم؟', 'لولا الامتناعية', 'حرف امتناع لوجود؛ يمتنع جوابها لوجود شرطها، ويأتي بعدها مبتدأ خبره محذوف وجوبا.', 'فلولاها لبقيت الحكمة حبيسة لغتها.'),
      ('ابن خلدون: العمران البشري وفلسفة التاريخ', 'اسم الفاعل العامل', 'اسم الفاعل قد يعمل عمل فعله فيرفع فاعلا وينصب مفعولا إذا اعتمد على مبتدأ أو موصوف ودل على الحال أو الاستقبال.', 'الظلم مؤذن بخراب العمران — مؤذن اسم فاعل خبر عمل في الجار والمجرور.'),
      ('ابن خلدون: العمران البشري وفلسفة التاريخ', 'أفعل التفضيل', 'اسم على وزن أفعل يدل على اشتراك شيئين في صفة وزيادة أحدهما فيها، ويستعمل في الموازنة والحجاج.', 'ما خالف طبائع العمران فهو إلى الكذب أقرب.'),
      ('الجاحظ وفنّ المقالة', 'الإطناب والإيجاز', 'الإطناب زيادة اللفظ على المعنى لفائدة كالتوكيد أو الإيضاح، والإيجاز أداء المعنى بأقل من اللفظ المعتاد، وكلاهما بلاغة إذا وافق مقتضى الحال.', 'يردف الجملة بأختها ليستوفي المعنى من جهاته كلها — إطنابٌ غايته الإحاطة.'),
      ('الجاحظ وفنّ المقالة', 'الحال المؤكدة', 'قد تأتي الحال مؤكدة لعاملها أو لمضمون الجملة، فلا تفيد هيئة جديدة بل توكيدًا، وتُنصب على الحالية.', 'كان يستطرد عامدًا متعمدًا — حالان مؤكدتان لمعنى الفعل.'),
      ('المتنبي وصورة الذات', 'التقديم والتأخير لإفادة القصر', 'تقديم ما حقه التأخير، كالمفعول أو الخبر، يفيد قصر الحكم على المتقدَّم وتخصيصه به، وهو من أسرار البلاغة في تشكيل المعنى.', 'بالممالك يبيع قصائده لا بالدراهم — قُدّم الجار والمجرور لإفادة التخصيص.'),
      ('المتنبي وصورة الذات', 'الاستثناء المنقطع والمتصل', 'المتصل ما كان المستثنى فيه من جنس المستثنى منه، والمنقطع ما لم يكن، ويترتب على ذلك حكم النصب أو جواز الإتباع.', 'خسر كل شيء سوى الخلود — استثناء بسوى، والمستثنى مجرور بالإضافة.'),
      ('النقد الأدبي الحديث', 'إعراب الجمل', 'الجمل بعد النكرات صفات وبعد المعارف أحوال، وقد تقع الجملة خبرًا أو مضافًا إليها فيكون لها محل من الإعراب، أو تكون استئنافية فلا محل لها.', 'مناهج تتوسل بالمفاهيم — جملة تتوسل في محل جر صفة لمناهج.'),
      ('النقد الأدبي الحديث', 'حذف حرف العلة من المضارع المجزوم', 'إذا جُزم الفعل المضارع المعتل الآخر حُذف حرف العلة وكان الحذف علامة جزمه.', 'لم يلغِ النقدُ الذوقَ — حذفت الياء علامة للجزم.'),
      ('فلسفة العدل عند الفلاسفة المسلمين', 'المفعول لأجله', 'مصدر قلبي منصوب يبين علة الفعل، ويشترط اتحاده مع الفعل في الزمن والفاعل، فإن فقد شرطًا جُرّ بحرف التعليل.', 'تضافرت الأخلاق والسياسة طلبًا للسعادة — طلبًا مفعول لأجله.'),
      ('فلسفة العدل عند الفلاسفة المسلمين', 'أوشك من أفعال المقاربة', 'أوشك تعمل عمل كان، ترفع الاسم ويكون خبرها جملة مضارعة، ويغلب اقترانها بأن أو تجردها منها.', 'من عدل في نفسه أوشك أن يعدل في رعيته.'),
      ('لغة القرآن وأثرها في العربية', 'نائب الفاعل', 'إذا بُني الفعل للمجهول ناب المفعول أو الجار والمجرور عن الفاعل وارتفع، ويُضم أول الماضي ويكسر ما قبل آخره.', 'وُضع النحو ودُوّنت المعاجم ورُحل إلى البوادي.'),
      ('لغة القرآن وأثرها في العربية', 'التضمين', 'إشراب فعلٍ معنى فعل آخر فيتعدى تعديته، وهو باب واسع في فهم تعدية الأفعال بحروف غير المعهودة معها.', 'حار البلاغيون في نظمه — ضُمّن حار معنى تأمل فتعدى بفي.'),
      ('السرد في ألف ليلة وليلة', 'أسلوب الشرط وجوابه', 'تربط أدوات الشرط فعلين يتوقف ثانيهما على أولهما، ويقترن الجواب بالفاء إذا كان جملة اسمية أو طلبية أو ممتنعة عن الجزم.', 'احكِ لي حكاية أعجب فأهب لك ثلث دم الرجل — جواب الطلب منصوب أو مجزوم على التأويلين.'),
      ('السرد في ألف ليلة وليلة', 'الجناس والطباق', 'الجناس تشابه اللفظين مع اختلاف المعنى، والطباق الجمع بين الضدين، وكلاهما من المحسنات البديعية إذا جاء عفوًا غير متكلف.', 'انتصار السرد على السيف — تقابل بين أداة الحياة وأداة الموت يقارب الطباق المعنوي.'),
      ('النهضة العربية الحديثة', 'الحال الجامدة المؤولة بالمشتق', 'الأصل في الحال أن تكون مشتقة، وقد تأتي جامدة مؤولة بمشتق كما في الدلالة على الترتيب أو التشبيه.', 'تستلهم التراث وتقتبس من الحداثة في آن — وجملة تستلهم حال من النهضة بتأويل مستلهمةً.'),
      ('النهضة العربية الحديثة', 'تمييز النسبة المحوّل', 'قد يكون التمييز محولًا عن مبتدأ أو فاعل أو مفعول، فيُنصب رفعًا للإبهام عن النسبة في الجملة.', 'ولدت النهضة حركةً مزدوجة الوجه — مزدوجةَ الوجهِ من باب الإضافة الرافعة للإبهام.'),
      ('إشكالية الفصحى والعامية', 'قلّ وكاد في النفي المضمر', 'قلّ أن يفيد ندرة الوقوع وهو قريب من النفي، ويليه المصدر المؤول فاعلًا له.', 'قلّ أن عرفت أمة ازدواجًا بمثل هذا — المصدر المؤول فاعل قلّ.'),
      ('الترجمة الأدبية وحدودها', 'الاشتغال', 'أن يتقدم اسم ويشتغل عنه الفعل بضميره، فيجوز في الاسم الرفع على الابتداء والنصب بفعل مضمر يفسره المذكور.', 'الشعر إذا تُرجم ذهب رونقه — ويجوز في غير هذا السياق: الشعرَ ترجمتُه عسيرة بالنصب على الاشتغال.'),
      ('جماليات الخط العربي', 'الالتفات', 'الانتقال في الكلام من ضمير إلى ضمير، كالغيبة إلى الخطاب، لتنشيط السامع وتلوين الأسلوب، وهو من خصائص البيان العربي الرفيع.', 'يصف النص الخط بضمير الغيبة ثم يقرّبه: حتى إذا وقفتَ أمامه أدركتَ جماله — التفات من الغيبة إلى الخطاب.')
  ) as g (lesson_title, title, explanation, example)
    on l.title = g.lesson_title;

