        ('فِي سُوقِ الْخُضَارِ وَالْفَوَاكِهِ', 'بِكَمْ كَانَ كِيلُو الطَّمَاطِمِ؟',
         array['بِثَلَاثَةِ دَرَاهِمَ', 'بِخَمْسَةِ دَرَاهِمَ', 'بِدِرْهَمٍ وَاحِدٍ']),
        ('فِي سُوقِ الْخُضَارِ وَالْفَوَاكِهِ', 'لِمَاذَا اشْتَرَوُا التُّفَّاحَ وَالْمَوْزَ؟',
         array['لِأَنَّ الْأَبَ يُحِبُّ الْفَوَاكِهَ', 'لِأَنَّ الْأُمَّ تُحِبُّ الطَّبْخَ', 'لِأَنَّ السِّعْرَ رَخِيصٌ']),
        ('هِوَايَتِي الْمُفَضَّلَةُ', 'مَا هِيَ هِوَايَةُ الْوَلَدِ الْمُفَضَّلَةُ؟',
         array['الرَّسْمُ', 'السِّبَاحَةُ', 'الْقِرَاءَةُ']),
