         array['لِجَدَّتِهِ', 'لِأُمِّهِ', 'لِمُعَلِّمِهِ']),
        ('هِوَايَتِي الْمُفَضَّلَةُ', 'مَاذَا يُرِيدُ أَنْ يَفْعَلَ فِي الْمُسْتَقْبَلِ؟',
