    ) as t (lesson_title, question, options)
  loop
    select id into v_lesson from public.lessons where title = q.lesson_title;
    if v_lesson is null then
      continue;
    end if;
    insert into public.lesson_exercises (lesson_id, question)
      values (v_lesson, q.question)
      returning id into v_exercise;
    insert into public.lesson_exercise_options (exercise_id, option_text, is_correct)
      select v_exercise, opt, ord = 1
      from unnest(q.options) with ordinality as o (opt, ord);
  end loop;
end $$;

